import type { MeaningPack } from '../../types';

export const taGitaVerses1: MeaningPack = {
  lang: 'ta',
  texts: {
    'bhagavad-gita-01': {
      verses: {
        '0.0': "த்ருதராஷ்டிரன் கேட்டான்: ஸஞ்ஜயா, தர்மக்ஷேத்திரமான குருக்ஷேத்திரத்தில் போர் புரியும் ஆவலுடன் கூடிய என் மக்களும் பாண்டவர்களும் என்ன செய்தனர்?",
        '0.1': "ஸஞ்ஜயன் கூறினான்: அணிவகுத்து நின்ற பாண்டவர் சேனையைக் கண்டு அரசன் துரியோதனன் ஆசார்யர் துரோணரை அணுகி இவ்வாறு கூறினான்.",
        '0.2': "\"ஆசார்யரே, உமது அறிவுமிக்க சீடனான த்ருபதன் மகன் அணிவகுத்த பாண்டு புத்திரர்களின் இந்த மாபெரும் சேனையைப் பாருங்கள்.\"",
        '0.3': "\"இங்கே போரில் பீமனுக்கும் அர்ஜுனனுக்கும் நிகரான பெரும் வில்லாளிகளான வீரர்கள் உள்ளனர்: யுயுதானன், விராடன், மகாரதனான த்ருபதன்;\"",
        '0.4': "\"த்ருஷ்டகேது, சேகிதானன், வீரமிக்க காசி அரசன், புருஜித், குந்திபோஜன், மனிதருள் சிறந்த சைப்யன்;\"",
        '0.5': "\"வீரனான யுதாமன்யு, வலிமைமிக்க உத்தமௌஜா, ஸுபத்ரையின் மகன் (அபிமன்யு), த்ரௌபதியின் மைந்தர்கள் — இவர்கள் அனைவரும் மகாரதர்கள்.\"",
        '0.6': "\"இருபிறப்பாளரில் சிறந்தவரே, நம் பக்கத்துச் சிறந்தவர்களை, என் சேனையின் தலைவர்களை அறிந்து கொள்ளுங்கள்; உங்கள் அறிவுக்காக அவர்களைச் சொல்கிறேன்.\"",
        '0.7': "\"நீங்கள், பீஷ்மர், கர்ணன், போரில் வெற்றி கொள்ளும் க்ருபர், அஸ்வத்தாமா, விகர்ணன், ஸோமதத்தனின் மகன் (பூரிஸ்ரவஸ்).\"",
        '0.8': "\"எனக்காக உயிரைத் துறக்கத் துணிந்த, பலவகை ஆயுதங்கள் ஏந்திய, போரில் வல்லமை பெற்ற இன்னும் பல வீரர்கள் உள்ளனர்.\"",
        '0.9': "\"பீஷ்மரால் காக்கப்படும் நம் சேனை அளவற்றது (அல்லது போதாதது); பீமனால் காக்கப்படும் அவர்களுடைய இச்சேனை அளவுக்குட்பட்டது (அல்லது போதுமானது).\"",
        '0.10': "\"ஆகவே நீங்கள் அனைவரும் அணிவகுப்பின் எல்லா வாயில்களிலும் உங்கள் உங்கள் இடங்களில் நின்று பீஷ்மரையே எல்லாப் புறமும் காக்க வேண்டும்.\"",
        '0.11': "அப்போது துரியோதனனுக்கு மகிழ்ச்சியூட்ட, குருகுலத்து மூத்தவரும் வீரமிக்கவருமான பாட்டனார் பீஷ்மர் சிங்கம் போல் உரக்க முழங்கிச் சங்கை ஊதினார்.",
        '0.12': "அப்போது சங்குகளும் பேரிகைகளும் பணவம், ஆனகம், கோமுகம் ஆகிய வாத்தியங்களும் ஒருசேர முழங்கின; அந்த ஒலி பேரிரைச்சலாக இருந்தது.",
        '0.13': "பின்னர் வெண்குதிரைகள் பூட்டிய பெரிய தேரில் அமர்ந்திருந்த மாதவனும் (கிருஷ்ணன்) பாண்டவனும் (அர்ஜுனன்) தங்கள் தெய்வீகச் சங்குகளை ஊதினர்.",
        '0.14': "ஹ்ருஷீகேசன் பாஞ்சஜன்யத்தையும், தனஞ்ஜயன் தேவதத்தத்தையும், அஞ்சத்தக்க செயல்களைச் செய்யும் வ்ருகோதரன் (பீமன்) பௌண்ட்ரம் என்ற பெரும் சங்கையும் ஊதினர்.",
        '0.15': "குந்தியின் மகனான அரசன் யுதிஷ்டிரன் அனந்தவிஜயத்தையும், நகுலனும் ஸஹதேவனும் ஸுகோஷம், மணிபுஷ்பகம் ஆகியவற்றையும் ஊதினர்.",
        '0.16': "சிறந்த வில்லாளியான காசி அரசன், மகாரதனான சிகண்டி, த்ருஷ்டத்யும்னன், விராடன், வெல்லப்படாத ஸாத்யகி;",
        '0.17': "பூமியின் தலைவனே, த்ருபதனும் த்ரௌபதியின் மைந்தர்களும் வலிய தோள்களுடைய ஸுபத்ரையின் மகனும் — அனைவரும் தனித்தனியே தம் சங்குகளை ஊதினர்.",
        '0.18': "வானையும் மண்ணையும் எதிரொலிக்கச் செய்த அந்தப் பேரொலி த்ருதராஷ்டிரன் மக்களின் இதயங்களைப் பிளந்தது.",
        '0.19': "அரசே, அப்போது போருக்கு அணிவகுத்து நிற்கும் த்ருதராஷ்டிரன் மக்களைக் கண்டு, ஆயுதங்கள் மோதத் தொடங்கும் வேளையில், அனுமக் கொடியோனான பாண்டவன் வில்லை உயர்த்தி ஹ்ருஷீகேசனிடம் இவ்வாறு கூறினான்.",
        '0.20': "அர்ஜுனன் கூறினான்: அச்யுதா, இரு சேனைகளுக்கும் நடுவே என் தேரை நிறுத்து,",
        '0.21': "போர் விருப்பத்துடன் நிற்கும் இவர்களை நான் பார்க்கும்படி — இந்தப் போர் முயற்சியில் நான் யாருடன் போரிட வேண்டும் என்று அறியும்படி,",
        '0.22': "தீய எண்ணமுடைய த்ருதராஷ்டிரன் மகனுக்குப் போரில் பிரியம் செய்ய விரும்பி இங்கே கூடியிருக்கும் போர்வீரர்களை நான் காண்பேன்.",
        '0.23': "ஸஞ்ஜயன் கூறினான்: பாரதா, குடாகேசன் (அர்ஜுனன்) இவ்வாறு சொன்னதும், ஹ்ருஷீகேசன் அந்தச் சிறந்த தேரை இரு சேனைகளுக்கும் நடுவே நிறுத்தி,",
        '0.24': "பீஷ்மர், துரோணர் மற்றும் எல்லா அரசர்களின் முன்னிலையில், \"பார்த்தா, இங்கே கூடியிருக்கும் இக்குருக்களைப் பார்\" என்றான்.",
        '0.25': "அங்கே பார்த்தன் இரு சேனைகளிலும் நிற்கும் தந்தையர், பாட்டனார், ஆசிரியர், தாய்மாமன்கள், சகோதரர், மைந்தர், பேரன்கள், நண்பர்கள் ஆகியோரைக் கண்டான்,",
        '0.26': "மாமனார்களையும் நலம் விரும்பிகளையும் கண்டான். அங்கு நின்ற அந்த உறவினர் அனைவரையும் பார்த்துக் குந்தியின் மகன் —",
        '0.27': "பெரும் இரக்கத்தால் ஆட்கொள்ளப்பட்டு வருந்தியவனாய் இவ்வாறு கூறினான். அர்ஜுனன் கூறினான்: கிருஷ்ணா, போரிட விரும்பி இங்கு நிற்கும் என் சுற்றத்தாரைக் கண்டு —",
        '0.28': "என் உறுப்புகள் தளர்கின்றன, வாய் உலர்கிறது, உடல் நடுங்குகிறது, மயிர் சிலிர்க்கிறது.",
        '0.29': "காண்டீவம் கையிலிருந்து நழுவுகிறது, தோல் எரிகிறது; நிற்கவும் இயலவில்லை, என் மனம் சுழல்வது போல் உள்ளது.",
        '0.30': "கேசவா, எதிரான சகுனங்களைக் காண்கிறேன்; போரில் என் உறவினரைக் கொன்று எந்த நன்மையையும் நான் காணவில்லை.",
        '0.31': "கிருஷ்ணா, எனக்கு வெற்றியும் வேண்டாம், அரசும் இன்பங்களும் வேண்டாம். கோவிந்தா, அரசாலோ இன்பங்களாலோ வாழ்வாலோ நமக்கு என்ன பயன்?",
        '0.32': "யாருக்காக நாம் அரசையும் இன்பங்களையும் சுகங்களையும் விரும்பினோமோ, அவர்களே உயிரையும் செல்வத்தையும் துறந்து போரில் நிற்கின்றனர்:",
        '0.33': "ஆசிரியர்கள், தந்தையர், மைந்தர், பாட்டனார், தாய்மாமன்கள், மாமனார்கள், பேரன்கள், மைத்துனர்கள் மற்றும் பிற உறவினர்.",
        '0.34': "மதுசூதனா, அவர்கள் என்னைக் கொன்றாலும் நான் அவர்களைக் கொல்ல விரும்பேன் — மூவுலக அரசுக்காகவும் இல்லை, இந்த மண்ணுக்காக என்ன?",
        '0.35': "ஜனார்த்தனா, த்ருதராஷ்டிரன் மக்களைக் கொன்று நமக்கு என்ன மகிழ்ச்சி? இந்த ஆததாயிகளைக் கொன்றால் நம்மைப் பாவமே பற்றும்.",
        '0.36': "ஆகவே நம் உறவினரான த்ருதராஷ்டிரன் மக்களைக் கொல்வது நமக்குத் தகாது. மாதவா, நம் சொந்தங்களைக் கொன்று நாம் எப்படி மகிழ்ந்திருப்போம்?",
        '0.37': "பேராசையால் அறிவு மழுங்கிய இவர்கள் குலத்தை அழிப்பதால் வரும் குற்றத்தையும் நண்பருக்குத் துரோகம் செய்யும் பாவத்தையும் காணாவிட்டாலும்,",
        '0.38': "ஜனார்த்தனா, குல அழிவின் குற்றத்தைத் தெளிவாகக் காணும் நாம் இந்தப் பாவத்திலிருந்து விலக வேண்டும் என்று ஏன் அறியக்கூடாது?",
        '0.39': "குலம் அழியும்போது தொன்றுதொட்ட குலதர்மங்கள் அழிகின்றன; தர்மம் அழிந்தால் குலம் முழுவதையும் அதர்மம் ஆட்கொள்கிறது.",
        '0.40': "கிருஷ்ணா, அதர்மம் மேலோங்கும்போது குலப் பெண்கள் கெடுகின்றனர்; வார்ஷ்ணேயா, பெண்கள் கெட்டால் வர்ணக் கலப்பு உண்டாகிறது.",
        '0.41': "இந்தக் கலப்பு குலத்தை அழித்தவர்களையும் குலத்தையும் நரகத்துக்கே இட்டுச் செல்கிறது; பிண்டமும் நீர்க்கடனும் நின்றுபோவதால் அவர்களுடைய பித்ருக்களும் வீழ்கின்றனர்.",
        '0.42': "வர்ணக் கலப்புக்குக் காரணமான குலத்தை அழிப்போரின் இக்குற்றங்களால் நிலையான ஜாதி தர்மங்களும் குல தர்மங்களும் அழிகின்றன.",
        '0.43': "ஜனார்த்தனா, குலதர்மங்கள் அழிந்த மனிதர்களுக்கு அளவற்ற காலம் நரகவாசம் உண்டு என்று நாம் கேட்டிருக்கிறோம்.",
        '0.44': "அந்தோ! அரசின்பப் பேராசையால் சொந்தங்களைக் கொல்லத் துணிந்து, எவ்வளவு பெரும் பாவத்தைச் செய்ய நாம் முடிவு செய்துவிட்டோம்!",
        '0.45': "ஆயுதமின்றி எதிர்க்காமல் இருக்கும் என்னை ஆயுதமேந்திய த்ருதராஷ்டிரன் மக்கள் போரில் கொன்றாலும் அதுவே எனக்கு மேலான நலம்.",
        '0.46': "ஸஞ்ஜயன் கூறினான்: போர்க்களத்தில் இவ்வாறு கூறிவிட்டு, துயரத்தால் கலங்கிய மனத்துடன் அர்ஜுனன் அம்புகளுடன் வில்லைக் கீழே போட்டுத் தேர்த்தட்டில் அமர்ந்துவிட்டான்.",
        '0.47': "ஓம் தத் ஸத். உபநிஷத்தும் பிரம்மவித்யையும் யோகசாஸ்திரமுமான ஸ்ரீமத் பகவத்கீதையில், ஸ்ரீகிருஷ்ண-அர்ஜுன உரையாடலில் \"அர்ஜுன விஷாத யோகம்\" என்னும் முதல் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'bhagavad-gita-02': {
      verses: {
        '0.0': "ஸஞ்ஜயன் கூறினான்: இவ்வாறு இரக்கத்தால் ஆட்கொள்ளப்பட்டு, கண்ணீர் நிறைந்த கலங்கிய கண்களுடன் வருந்திக்கொண்டிருந்த அவனிடம் மதுசூதனன் இச்சொற்களைக் கூறினான்.",
        '0.1': "ஸ்ரீ பகவான் கூறினார்: அர்ஜுனா, இந்த நெருக்கடியான வேளையில் இந்த மயக்கம் உனக்கு எங்கிருந்து வந்தது? இது சான்றோருக்குத் தகாதது, சுவர்க்கம் தராதது, அவப்புகழ் தருவது.",
        '0.2': "பார்த்தா, பேடித்தனத்துக்கு இடம் கொடாதே; இது உனக்குப் பொருந்தாது. பகைவரை வாட்டுபவனே, இந்த அற்பமான மனத்தளர்ச்சியை விட்டு எழுந்திரு.",
        '0.3': "அர்ஜுனன் கூறினான்: மதுசூதனா, பகைவரை அழிப்பவனே, வணங்கத் தக்கவர்களான பீஷ்மரையும் துரோணரையும் போரில் அம்புகளால் நான் எப்படி எதிர்ப்பேன்?",
        '0.4': "பெருமைமிக்க குருமார்களைக் கொல்வதைவிட இவ்வுலகில் பிச்சை எடுத்து வாழ்வதே மேல். குருக்களைக் கொன்றால் இங்கேயே இரத்தம் தோய்ந்த இன்பங்களையே அனுபவிப்பேன்.",
        '0.5': "நாம் வெல்வதா, அவர்கள் நம்மை வெல்வதா — எது மேலானது என்றும் நமக்குத் தெரியவில்லை. யாரைக் கொன்றபின் நாம் வாழ விரும்ப மாட்டோமோ அந்த த்ருதராஷ்டிரன் மக்களே எதிரில் நிற்கின்றனர்.",
        '0.6': "கோழைத்தனம் என்ற குறையால் இயல்பு பாதிக்கப்பட்டு, தர்மம் பற்றி மனம் குழம்பி உன்னிடம் கேட்கிறேன்: எனக்கு உறுதியாக நன்மை தருவது எதுவோ அதைச் சொல். நான் உன் சீடன்; உன்னைச் சரணடைந்த எனக்கு அறிவுரை கூறு.",
        '0.7': "மண்ணில் பகையற்ற செழிப்பான அரசையும் தேவர்கள் மீது ஆட்சியையும் பெற்றாலும், புலன்களை வாட்டும் இந்தத் துயரைப் போக்கக்கூடியது எதையும் நான் காணவில்லை.",
        '0.8': "ஸஞ்ஜயன் கூறினான்: பகைவரை வாட்டும் குடாகேசன் ஹ்ருஷீகேசனிடம் இவ்வாறு கூறி, \"நான் போரிட மாட்டேன்\" என்று கோவிந்தனிடம் சொல்லி மௌனமானான்.",
        '0.9': "பாரதா, இரு சேனைகளுக்கும் நடுவே வருந்திக்கொண்டிருந்த அவனிடம் ஹ்ருஷீகேசன் புன்னகைப்பவன் போல இச்சொற்களைக் கூறினான்.",
        '0.10': "ஸ்ரீ பகவான் கூறினார்: வருந்தத் தகாதவர்களுக்காக நீ வருந்துகிறாய்; ஆனாலும் அறிவாளி போலப் பேசுகிறாய். ஞானிகள் இறந்தவர்களுக்காகவோ உயிரோடிருப்பவர்களுக்காகவோ வருந்துவதில்லை.",
        '0.11': "நானோ நீயோ இந்த அரசர்களோ இல்லாதிருந்த காலம் எப்போதும் இல்லை; இனிமேலும் நாம் யாரும் இல்லாமல் போவதில்லை.",
        '0.12': "உடலை உடையவனுக்கு இவ்வுடலில் குழந்தைப் பருவம், இளமை, முதுமை வருவது போலவே வேறு உடலை அடைவதும்; தீரன் இதில் மயங்குவதில்லை.",
        '0.13': "குந்தியின் மகனே, புலன்கள் பொருள்களோடு தொடர்புகொள்வதால் குளிர்-வெப்பம், இன்பம்-துன்பம் உண்டாகின்றன; அவை வந்து போகக்கூடியவை, நிலையற்றவை. பாரதா, அவற்றைப் பொறுத்துக்கொள்.",
        '0.14': "மனிதருள் சிறந்தவனே, இன்ப துன்பங்களில் சமமாக இருந்து, இவற்றால் கலங்காத தீரன் அமரத்துவத்துக்கு (மோக்ஷத்துக்கு) தகுதி பெறுகிறான்.",
        '0.15': "இல்லாததற்கு இருப்பு இல்லை; உள்ளதற்கு இன்மை இல்லை; இவ்விரண்டின் உண்மை நிலையைத் தத்துவ தரிசிகள் கண்டுள்ளனர்.",
        '0.16': "எதனால் இவையனைத்தும் வியாபிக்கப்பட்டுள்ளதோ அதை அழிவற்றது என்று அறி. அழியாத அதனை யாராலும் அழிக்க இயலாது.",
        '0.17': "நித்தியமானவனும் அழிவற்றவனும் அளவிட முடியாதவனுமான ஆத்மாவின் இவ்வுடல்கள் முடிவுடையவை எனப்படுகின்றன. ஆகவே பாரதா, போர் செய்.",
        '0.18': "இந்த ஆத்மாவைக் கொல்பவன் என்று நினைப்பவனும் கொல்லப்பட்டவன் என்று நினைப்பவனும் — இருவரும் அறியாதவர்கள். இது கொல்வதுமில்லை, கொல்லப்படுவதுமில்லை.",
        '0.19': "இது ஒருபோதும் பிறப்பதுமில்லை, இறப்பதுமில்லை; இருந்து பின் இல்லாமல் போவதுமில்லை. பிறப்பற்றது, நித்தியமானது, நிலையானது, தொன்மையானது; உடல் கொல்லப்படும்போதும் இது கொல்லப்படுவதில்லை.",
        '0.20': "பார்த்தா, இதை அழிவற்றது, நித்தியமானது, பிறப்பற்றது, மாறாதது என்று அறிந்தவன் யாரை எப்படிக் கொல்விப்பான், யாரைக் கொல்வான்?",
        '0.21': "மனிதன் பழைய ஆடைகளைக் களைந்து புதியவற்றை அணிவது போல, ஆத்மா பழைய உடல்களைக் கைவிட்டுப் புதிய உடல்களை அடைகிறது.",
        '0.22': "இதை ஆயுதங்கள் வெட்டா, நெருப்பு எரிக்காது, நீர் நனைக்காது, காற்று உலர்த்தாது.",
        '0.23': "இது வெட்டப்பட முடியாதது, எரிக்கப்பட முடியாதது, நனைக்கப்பட முடியாதது, உலர்த்தப்பட முடியாதது. நித்தியமானது, எங்கும் நிறைந்தது, நிலையானது, அசையாதது, என்றுமுள்ளது.",
        '0.24': "இது வெளிப்படாதது, சிந்தனைக்கு எட்டாதது, மாறுபாடற்றது எனப்படுகிறது. ஆகவே இதை இவ்வாறு அறிந்து நீ வருந்தலாகாது.",
        '0.25': "வலிய தோளனே, இதை எப்போதும் பிறப்பதாகவும் எப்போதும் இறப்பதாகவும் நீ கருதினாலும், அப்போதும் இவ்வாறு வருந்துவது தகாது.",
        '0.26': "பிறந்தவனுக்கு இறப்பு உறுதி; இறந்தவனுக்குப் பிறப்பு உறுதி. ஆகவே தவிர்க்க முடியாத விஷயத்தில் நீ வருந்தலாகாது.",
        '0.27': "பாரதா, உயிர்கள் தொடக்கத்தில் வெளிப்படாதவை, இடையில் வெளிப்பட்டவை, முடிவில் மீண்டும் வெளிப்படாதவை. இதில் புலம்புவதற்கு என்ன இருக்கிறது?",
        '0.28': "ஒருவன் இதை வியப்பாகக் காண்கிறான், மற்றொருவன் வியப்பாகப் பேசுகிறான், இன்னொருவன் வியப்பாகக் கேட்கிறான்; கேட்ட பின்னும் இதை யாரும் உண்மையில் அறிவதில்லை.",
        '0.29': "பாரதா, எல்லாருடைய உடலிலும் உறையும் இந்த ஆத்மா எப்போதும் கொல்லப்பட முடியாதது. ஆகவே எந்த உயிருக்காகவும் நீ வருந்தலாகாது.",
        '0.30': "உன் ஸ்வதர்மத்தைக் கருதினாலும் நீ தடுமாறலாகாது; க்ஷத்திரியனுக்கு அறப்போரைவிட மேலான நன்மை வேறில்லை.",
        '0.31': "பார்த்தா, தானாக வந்தடைந்த, திறந்த சுவர்க்க வாயில் போன்ற இத்தகைய போரை நற்பேறு பெற்ற க்ஷத்திரியர்களே அடைகின்றனர்.",
        '0.32': "ஆனால் நீ இந்த அறப்போரைச் செய்யாவிட்டால், ஸ்வதர்மத்தையும் புகழையும் இழந்து பாவத்தை அடைவாய்.",
        '0.33': "மக்கள் உன் நீங்காத இகழ்ச்சியைப் பேசுவார்கள்; மதிக்கப்பட்டவனுக்கு இகழ்ச்சி மரணத்தைவிடக் கொடியது.",
        '0.34': "அச்சத்தால் போரிலிருந்து விலகினாய் என்று மகாரதர்கள் கருதுவார்கள்; யாரால் நீ பெரிதும் மதிக்கப்பட்டாயோ அவர்கள் முன் இழிவடைவாய்.",
        '0.35': "உன் பகைவர்கள் உன் வல்லமையை இகழ்ந்து, சொல்லத்தகாத பல சொற்களைச் சொல்வார்கள். அதைவிடத் துன்பம் வேறென்ன?",
        '0.36': "கொல்லப்பட்டால் சுவர்க்கம் அடைவாய்; வென்றால் பூமியை அனுபவிப்பாய். ஆகவே குந்தியின் மகனே, போருக்கு உறுதிகொண்டு எழுந்திரு.",
        '0.37': "இன்ப-துன்பம், இலாப-நஷ்டம், வெற்றி-தோல்வி ஆகியவற்றைச் சமமாகக் கருதிப் போருக்குத் தயாராகு; இவ்வாறு செய்தால் பாவம் உன்னை அடையாது.",
        '0.38': "பார்த்தா, இந்த அறிவு உனக்கு ஸாங்கியத்தின் (ஞானத்தின்) வழியில் சொல்லப்பட்டது; இனி யோகத்தின் வழியில் கேள் — இதனோடு கூடியவனாய் வினைப் பிணைப்பை நீ நீக்குவாய்.",
        '0.39': "இந்நெறியில் முயற்சி வீணாவதில்லை; எதிர்விளைவும் இல்லை. இந்த தர்மத்தின் சிறிதளவும் பெரும் அச்சத்திலிருந்து காக்கிறது.",
        '0.40': "குருநந்தனா, இங்கே உறுதியான அறிவு ஒன்றே; உறுதியற்றவர்களின் எண்ணங்களோ பல கிளைகளுடையவை, முடிவற்றவை.",
        '0.41': "பார்த்தா, வேதங்களின் கர்மபல வாக்கியங்களிலேயே மகிழ்ந்து, \"இதைத் தவிர வேறில்லை\" என்று சொல்லும் அறிவிலிகள் மலர் போன்ற கவர்ச்சியான சொற்களைப் பேசுகின்றனர் —",
        '0.42': "அவர்கள் ஆசை நிறைந்தவர்கள், சுவர்க்கமே இலக்கு என்பவர்கள்; அவர்களுடைய சொற்கள் பிறவி என்னும் வினைப்பயனைத் தருபவை, இன்பமும் செல்வமும் பெறப் பல சிறப்புச் சடங்குகளை விவரிப்பவை.",
        '0.43': "இன்பத்திலும் செல்வத்திலும் பற்றுக்கொண்டு, அச்சொற்களால் மனம் கவரப்பட்டவர்களுக்கு ஸமாதியில் நிலைத்த உறுதியான அறிவு உண்டாவதில்லை.",
        '0.44': "வேதங்கள் முக்குணங்களைப் பற்றியவை; அர்ஜுனா, நீ முக்குணங்களைக் கடந்தவனாகு — இருமைகளற்றவனாய், என்றும் ஸத்வத்தில் நிலைத்தவனாய், பெறுவது காப்பது பற்றிய கவலையற்றவனாய், தன்னடக்கம் உள்ளவனாய் இரு.",
        '0.45': "எங்கும் நீர் நிரம்பி வழியும்போது சிறு கிணற்றால் எவ்வளவு பயனோ, அறிந்த பிராம்மணனுக்கு எல்லா வேதங்களிலும் அவ்வளவே பயன்.",
        '0.46': "செயல் புரிவதில் மட்டுமே உனக்கு உரிமை; அதன் பலன்களில் ஒருபோதும் இல்லை. பலனுக்காகச் செயல்படாதே; செயலின்மையிலும் உனக்குப் பற்று வேண்டாம்.",
        '0.47': "தனஞ்ஜயா, யோகத்தில் நிலைத்து, பற்றைத் துறந்து, வெற்றி தோல்விகளில் சமமாக இருந்து செயல்களைச் செய். இந்தச் சமநிலையே யோகம் எனப்படுகிறது.",
        '0.48': "தனஞ்ஜயா, (பலனை விரும்பிச் செய்யும்) செயல் புத்தியோகத்தைவிட மிகவும் தாழ்ந்தது. இந்த அறிவில் புகலிடம் தேடு; பலனுக்காகச் செயல்படுவோர் இரங்கத்தக்கவர்கள்.",
        '0.49': "இந்த அறிவுடையவன் இங்கேயே நல்வினை தீவினை இரண்டையும் நீக்குகிறான். ஆகவே யோகத்தில் ஈடுபடு; செயலில் திறமையே யோகம்.",
        '0.50': "இந்த அறிவுடைய ஞானியர் வினையால் விளையும் பலனைத் துறந்து, பிறவித் தளையிலிருந்து விடுபட்டு, துன்பமற்ற நிலையை அடைகின்றனர்.",
        '0.51': "உன் அறிவு மயக்கம் என்னும் சேற்றைக் கடக்கும்போது, கேட்டவற்றிலும் கேட்கவேண்டியவற்றிலும் நீ பற்றற்றவனாவாய்.",
        '0.52': "பலவிதச் சுருதி வாக்கியங்களால் குழம்பிய உன் அறிவு ஸமாதியில் அசையாமல் உறுதியாக நிற்கும்போது நீ யோகத்தை அடைவாய்.",
        '0.53': "அர்ஜுனன் கூறினான்: கேசவா, ஸமாதியில் நிலைத்த ஸ்திதப்ரஜ்ஞனின் இலக்கணம் என்ன? நிலைத்த அறிவுடையவன் எப்படிப் பேசுவான், எப்படி அமர்வான், எப்படி நடப்பான்?",
        '0.54': "ஸ்ரீ பகவான் கூறினார்: பார்த்தா, மனத்தில் எழும் எல்லா ஆசைகளையும் முழுமையாகத் துறந்து, தன்னால் தன்னிலேயே திருப்தியடையும்போது ஒருவன் ஸ்திதப்ரஜ்ஞன் எனப்படுகிறான்.",
        '0.55': "துன்பங்களில் கலங்காத மனமுடையவனும் இன்பங்களில் ஆசையற்றவனும் பற்று, அச்சம், சினம் நீங்கியவனுமான முனிவன் நிலைத்த அறிவுடையவன் எனப்படுகிறான்.",
        '0.56': "எங்கும் பற்றற்றவனாய், நல்லது கிடைக்கும்போது களிக்காமலும் தீயது கிடைக்கும்போது வெறுக்காமலும் இருப்பவனின் அறிவு நிலைபெற்றது.",
        '0.57': "ஆமை தன் உறுப்புகளை எல்லாப் புறமும் உள்ளிழுத்துக்கொள்வது போல, ஒருவன் புலன்களைப் புலனுகர் பொருள்களிலிருந்து விலக்கும்போது அவனது அறிவு நிலைபெற்றது.",
        '0.58': "புலனுகர்ச்சியைத் தவிர்ப்பவனிடமிருந்து பொருள்கள் விலகுகின்றன; ஆனால் சுவை எஞ்சுகிறது; பரம்பொருளைக் கண்டபின் அந்தச் சுவையும் நீங்குகிறது.",
        '0.59': "குந்தியின் மகனே, முயலும் அறிவாளியின் மனத்தையும் கலக்கும் புலன்கள் வலிந்து இழுத்துச் செல்கின்றன.",
        '0.60': "அவை அனைத்தையும் அடக்கி, என்னையே பரமாகக் கொண்டு யோகத்தில் அமர வேண்டும். யாருடைய புலன்கள் வசப்பட்டுள்ளனவோ அவனது அறிவு நிலைபெற்றது.",
        '0.61': "புலனுகர் பொருள்களை எண்ணிக்கொண்டிருப்பவனுக்கு அவற்றில் பற்று உண்டாகிறது; பற்றிலிருந்து ஆசையும் ஆசையிலிருந்து சினமும் பிறக்கின்றன.",
        '0.62': "சினத்திலிருந்து மயக்கம், மயக்கத்திலிருந்து நினைவுக் குழப்பம், நினைவழிவிலிருந்து அறிவழிவு; அறிவழிந்தால் அவன் அழிகிறான்.",
        '0.63': "ஆனால் மனத்தை அடக்கியவன், விருப்பு வெறுப்பற்றதும் தன் வசப்பட்டதுமான புலன்களோடு பொருள்களிடையே இயங்கி, தெளிந்த அமைதியை அடைகிறான்.",
        '0.64': "அந்தத் தெளிவில் அவனுடைய எல்லாத் துன்பங்களும் நீங்குகின்றன; தெளிந்த மனமுடையவனின் அறிவு விரைவில் நிலைபெறுகிறது.",
        '0.65': "யோகத்தில் இணையாதவனுக்கு அறிவு இல்லை, தியானமும் இல்லை; தியானமில்லாதவனுக்கு அமைதி இல்லை; அமைதியற்றவனுக்கு இன்பம் ஏது?",
        '0.66': "அலையும் புலன்களை மனம் பின்தொடர்ந்தால், நீரில் படகைக் காற்று அடித்துச் செல்வது போல அது அவனது அறிவைக் கவர்ந்து செல்கிறது.",
        '0.67': "ஆகவே வலிய தோளனே, யாருடைய புலன்கள் பொருள்களிலிருந்து முழுமையாக அடக்கப்பட்டுள்ளனவோ அவனது அறிவு நிலைபெற்றது.",
        '0.68': "எல்லா உயிர்களுக்கும் எது இரவோ அதில் தன்னடக்கமுடையவன் விழித்திருக்கிறான்; உயிர்கள் எதில் விழித்திருக்கின்றனவோ அது உண்மையைக் காணும் முனிவனுக்கு இரவு.",
        '0.69': "நிரம்பிக்கொண்டிருந்தும் அசையாது நிலைத்திருக்கும் கடலில் நீர் புகுவது போல, எல்லா ஆசைகளும் யாரிடம் புகுந்தும் அவனைக் கலக்கவில்லையோ அவனே அமைதி அடைகிறான்; ஆசைகளை விரும்புபவன் அல்ல.",
        '0.70': "எல்லா ஆசைகளையும் துறந்து, ஏக்கமின்றி, \"எனது\" என்ற எண்ணமும் அகந்தையும் இன்றி வாழ்பவன் அமைதியை அடைகிறான்.",
        '0.71': "பார்த்தா, இதுவே பிராம்மீ நிலை; இதை அடைந்தவன் மீண்டும் மயங்குவதில்லை. இறுதிக் காலத்திலும் இதில் நிலைத்தவன் பிரம்ம நிர்வாணத்தை அடைகிறான்.",
        '0.72': "ஓம் தத் ஸத். உபநிஷத்தும் பிரம்மவித்யையும் யோகசாஸ்திரமுமான ஸ்ரீமத் பகவத்கீதையில், ஸ்ரீகிருஷ்ண-அர்ஜுன உரையாடலில் \"ஸாங்கிய யோகம்\" என்னும் இரண்டாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'bhagavad-gita-03': {
      verses: {
        '0.0': "அர்ஜுனன் கூறினான்: ஜனார்த்தனா, செயலைவிட அறிவே மேலானது என்பது உன் கருத்தானால், கேசவா, இந்தக் கொடிய செயலில் என்னை ஏன் ஈடுபடுத்துகிறாய்?",
        '0.1': "கலந்தது போன்ற சொற்களால் என் அறிவைக் குழப்புவது போல் உள்ளது. நான் நன்மையை அடையக்கூடிய ஒன்றை உறுதியாகச் சொல்.",
        '0.2': "ஸ்ரீ பகவான் கூறினார்: பாவமற்றவனே, இவ்வுலகில் இருவகை நெறிகள் முன்பே என்னால் கூறப்பட்டன — ஸாங்கியர்களுக்கு ஞானயோகம், யோகிகளுக்குக் கர்மயோகம்.",
        '0.3': "செயல்களைத் தொடங்காமல் இருப்பதால் மனிதன் செயலற்ற நிலையை அடைவதில்லை; வெறும் துறவால் மட்டும் சித்தியை அடைவதுமில்லை.",
        '0.4': "யாரும் ஒரு கணமும் செயல் புரியாமல் இருக்க இயலாது; இயற்கையில் பிறந்த குணங்களால் எல்லாரும் தம்வசமின்றிச் செயல்பட வைக்கப்படுகின்றனர்.",
        '0.5': "செயல்புலன்களை அடக்கிவிட்டு மனத்தால் புலனுகர் பொருள்களை நினைத்துக்கொண்டிருக்கும் மூடன் போலி ஒழுக்கமுடையவன் எனப்படுகிறான்.",
        '0.6': "அர்ஜுனா, ஆனால் மனத்தால் புலன்களை அடக்கி, பற்றின்றிச் செயல்புலன்களால் கர்மயோகத்தைச் செய்பவன் சிறந்தவன்.",
        '0.7': "விதிக்கப்பட்ட கடமையைச் செய்; செயலின்மையைவிடச் செயலே மேலானது. செயல் இன்றி உன் உடல் வாழ்க்கையும் நடைபெறாது.",
        '0.8': "யஜ்ஞத்துக்காக (இறைவனுக்கு அர்ப்பணமாகச்) செய்யப்படும் செயலைத் தவிரப் பிற செயல்களால் இவ்வுலகம் கட்டுப்படுகிறது. ஆகவே குந்தியின் மகனே, பற்றின்றி அதற்காகவே செயல் புரி.",
        '0.9': "தொடக்கத்தில் பிரஜாபதி யஜ்ஞத்தோடு உயிர்களைப் படைத்துச் சொன்னார்: \"இதனால் நீங்கள் பெருகுங்கள்; இது உங்கள் விருப்பங்களை நிறைவேற்றும் காமதேனுவாகட்டும்.\"",
        '0.10': "\"இதனால் தேவர்களைப் போற்றுங்கள்; அத்தேவர்கள் உங்களைப் பேணட்டும்; இவ்வாறு ஒருவரையொருவர் பேணி நீங்கள் பரம நன்மையை அடைவீர்கள்.\"",
        '0.11': "\"யஜ்ஞத்தால் மகிழ்ந்த தேவர்கள் நீங்கள் விரும்பும் இன்பங்களைத் தருவார்கள்.\" அவர்கள் தந்தவற்றை அவர்களுக்குப் படைக்காமல் தானே அனுபவிப்பவன் திருடனே.",
        '0.12': "யஜ்ஞத்தின் மீதியை உண்ணும் நல்லோர் எல்லாப் பாவங்களிலிருந்தும் விடுபடுகின்றனர்; தமக்காக மட்டுமே சமைக்கும் பாவிகள் பாவத்தையே உண்கின்றனர்.",
        '0.13': "உணவிலிருந்து உயிர்கள் தோன்றுகின்றன; மழையிலிருந்து உணவு உண்டாகிறது; யஜ்ஞத்திலிருந்து மழை வருகிறது; யஜ்ஞம் செயலிலிருந்து பிறக்கிறது.",
        '0.14': "செயல் வேதத்திலிருந்து (பிரம்மத்திலிருந்து) தோன்றியது; வேதம் அழிவற்றவனிடமிருந்து தோன்றியது என்று அறி. ஆகவே எங்கும் நிறைந்த பிரம்மம் எப்போதும் யஜ்ஞத்தில் நிலைபெற்றுள்ளது.",
        '0.15': "பார்த்தா, இவ்வாறு இயக்கப்பட்ட சக்கரத்தை இவ்வுலகில் பின்பற்றாதவன் பாவ வாழ்க்கை வாழ்பவன், புலன் இன்பத்தில் திளைப்பவன்; அவன் வீணாக வாழ்கிறான்.",
        '0.16': "ஆனால் ஆத்மாவிலேயே மகிழ்ந்து, ஆத்மாவிலேயே திருப்தியடைந்து, ஆத்மாவிலேயே மனநிறைவு கொண்ட மனிதனுக்குச் செய்ய வேண்டிய கடமை எதுவும் இல்லை.",
        '0.17': "அவனுக்கு இங்கே செயலால் அடைவது எதுவும் இல்லை; செயலின்மையால் இழப்பதும் இல்லை; எந்த உயிரையும் எந்தப் பயனுக்காகவும் அவன் சார்ந்திருப்பதில்லை.",
        '0.18': "ஆகவே எப்போதும் பற்றின்றிச் செய்ய வேண்டிய செயலைச் செம்மையாகச் செய்; பற்றின்றிச் செயல்புரியும் மனிதன் பரம்பொருளை அடைகிறான்.",
        '0.19': "ஜனகர் முதலியோர் செயலாலேயே சித்தியை அடைந்தனர். உலக நலனைக் (லோகஸங்க்ரஹம்) கருதியாவது நீ செயல் புரிய வேண்டும்.",
        '0.20': "சிறந்தவன் எதை எதைச் செய்கிறானோ மற்றவர்களும் அதையே செய்கின்றனர்; அவன் எதை அளவுகோலாக்குகிறானோ உலகம் அதைப் பின்பற்றுகிறது.",
        '0.21': "பார்த்தா, மூவுலகிலும் நான் செய்ய வேண்டிய கடமை எதுவும் இல்லை; அடைய வேண்டிய அடையாதது எதுவும் இல்லை; இருந்தும் நான் செயலில் ஈடுபட்டிருக்கிறேன்.",
        '0.22': "பார்த்தா, நான் சோர்வின்றிச் செயலில் ஈடுபடாவிட்டால், மனிதர்கள் எல்லா விதத்திலும் என் வழியையே பின்பற்றுவார்கள்.",
        '0.23': "நான் செயல்படாவிட்டால் இவ்வுலகங்கள் அழிந்துவிடும்; நான் குழப்பத்துக்குக் காரணமாகி இந்த உயிர்களை அழித்தவனாவேன்.",
        '0.24': "பாரதா, செயலில் பற்றுடைய அறிவிலிகள் எப்படிச் செயல்புரிகிறார்களோ, அப்படியே அறிஞனும் உலக நலனை விரும்பிப் பற்றின்றிச் செயல்புரிய வேண்டும்.",
        '0.25': "செயலில் பற்றுடைய அறிவிலிகளின் மனத்தை அறிஞன் குழப்பக்கூடாது; தானே யோகத்துடன் செயல்களைச் செய்து அவர்களையும் எல்லாச் செயல்களிலும் ஈடுபடச் செய்ய வேண்டும்.",
        '0.26': "எல்லாச் செயல்களும் இயற்கையின் குணங்களாலேயே எல்லா விதத்திலும் நடைபெறுகின்றன; அகந்தையால் மயங்கியவன் \"நானே செய்பவன்\" என்று எண்ணுகிறான்.",
        '0.27': "வலிய தோளனே, குணங்கள் மற்றும் செயல்களின் பிரிவுகளைப் பற்றிய உண்மையை அறிந்தவன் \"குணங்கள் குணங்களிலேயே இயங்குகின்றன\" என்று உணர்ந்து பற்றுக்கொள்வதில்லை.",
        '0.28': "இயற்கையின் குணங்களால் மயங்கியவர்கள் குணங்களின் செயல்களில் பற்றுக்கொள்கின்றனர். முழுமையாக அறிந்தவன் அரைகுறை அறிவுடைய அந்த மந்தர்களைக் குழப்பக்கூடாது.",
        '0.29': "எல்லாச் செயல்களையும் ஆன்ம நாட்டமுள்ள மனத்துடன் எனக்கு அர்ப்பணித்து, ஆசையின்றி, \"எனது\" என்ற எண்ணமின்றி, மனக்கொதிப்பு நீங்கிப் போர் செய்.",
        '0.30': "நம்பிக்கையுடன், குறை காணாமல் என் இந்தக் கொள்கையை எப்போதும் பின்பற்றும் மனிதர்களும் வினைப் பிணைப்பிலிருந்து விடுபடுகின்றனர்.",
        '0.31': "ஆனால் குறை கூறி என் கொள்கையைப் பின்பற்றாதவர்களை எல்லா அறிவிலும் மயங்கியவர்கள், விவேகமற்றவர்கள், அழிந்தவர்கள் என்று அறி.",
        '0.32': "ஞானியும் தன் இயல்புக்கு ஏற்பவே நடக்கிறான்; உயிர்கள் தம் இயல்பையே பின்பற்றுகின்றன. வெறும் அடக்குமுறை என்ன செய்யும்?",
        '0.33': "ஒவ்வொரு புலனுக்கும் அதன் பொருளில் விருப்பும் வெறுப்பும் நிலைகொண்டுள்ளன. அவற்றின் வசப்படக்கூடாது; அவை ஒருவனின் வழியில் பகைவர்கள்.",
        '0.34': "நன்றாகச் செய்யப்பட்ட பிறர் தர்மத்தைவிடக் குறையுடையதானாலும் தன் தர்மமே மேலானது. தன் தர்மத்தில் இறப்பதும் நன்று; பிறர் தர்மம் அச்சம் தருவது.",
        '0.35': "அர்ஜுனன் கூறினான்: வார்ஷ்ணேயா, அப்படியானால் மனிதன் விரும்பாவிட்டாலும் வலிந்து தூண்டப்பட்டவன் போல எதனால் உந்தப்பட்டுப் பாவம் செய்கிறான்?",
        '0.36': "ஸ்ரீ பகவான் கூறினார்: ரஜோகுணத்தில் பிறந்த இந்த ஆசையே, இந்தச் சினமே; இது எல்லாவற்றையும் விழுங்குவது, பெரும் பாவமானது. இதையே இங்கே பகைவன் என்று அறி.",
        '0.37': "புகையால் நெருப்பும், அழுக்கால் கண்ணாடியும், கருப்பையால் கருவும் மூடப்படுவது போல, இதனால் (ஆசையால்) அறிவு மூடப்பட்டுள்ளது.",
        '0.38': "குந்தியின் மகனே, ஞானியரின் நிரந்தரப் பகைவனும் நெருப்பைப் போல் தணியாததுமான இந்த ஆசை வடிவத்தால் அறிவு மூடப்பட்டுள்ளது.",
        '0.39': "புலன்கள், மனம், அறிவு — இவை இதன் இருப்பிடம் எனப்படுகின்றன; இவற்றின் வழியாக இது அறிவை மறைத்து ஆத்மாவை மயக்குகிறது.",
        '0.40': "ஆகவே பரதர்களில் சிறந்தவனே, முதலில் புலன்களை அடக்கி, ஞானத்தையும் விஞ்ஞானத்தையும் அழிக்கும் இந்தப் பாவியை ஒழித்துவிடு.",
        '0.41': "புலன்கள் (உடலைவிட) உயர்ந்தவை என்பர்; புலன்களைவிட மனம் உயர்ந்தது; மனத்தைவிட அறிவு உயர்ந்தது; அறிவுக்கும் அப்பாற்பட்டவன் அவனே (ஆத்மா).",
        '0.42': "இவ்வாறு அறிவுக்கும் அப்பாற்பட்டதை அறிந்து, தன்னால் தன்னை நிலைப்படுத்தி, வலிய தோளனே, வெல்லக் கடினமான ஆசை வடிவப் பகைவனை அழித்துவிடு.",
        '0.43': "ஓம் தத் ஸத். உபநிஷத்தும் பிரம்மவித்யையும் யோகசாஸ்திரமுமான ஸ்ரீமத் பகவத்கீதையில், ஸ்ரீகிருஷ்ண-அர்ஜுன உரையாடலில் \"கர்ம யோகம்\" என்னும் மூன்றாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'bhagavad-gita-04': {
      verses: {
        '0.0': "ஸ்ரீ பகவான் கூறினார்: அழிவற்ற இந்த யோகத்தை நான் விவஸ்வானுக்கு (சூரியனுக்கு) உபதேசித்தேன்; விவஸ்வான் மனுவுக்கும், மனு இக்ஷ்வாகுவுக்கும் உரைத்தனர்.",
        '0.1': "இவ்வாறு குரு பரம்பரையாக வந்த இதை ராஜரிஷிகள் அறிந்திருந்தனர். பகைவரை வாட்டுபவனே, நீண்ட காலம் கடந்ததால் இந்த யோகம் இங்கே மறைந்துவிட்டது.",
        '0.2': "நீ என் பக்தனும் நண்பனுமாக இருப்பதால் அதே பழைய யோகத்தை இன்று உனக்கு உரைத்தேன்; இது உயர்ந்த ரகசியம்.",
        '0.3': "அர்ஜுனன் கூறினான்: உன் பிறப்பு பிற்காலத்தது; விவஸ்வானின் பிறப்போ முற்காலத்தது. தொடக்கத்தில் நீ இதை உபதேசித்தாய் என்பதை நான் எப்படி அறிவேன்?",
        '0.4': "ஸ்ரீ பகவான் கூறினார்: அர்ஜுனா, எனக்கும் உனக்கும் பல பிறவிகள் கடந்துவிட்டன. அவை அனைத்தையும் நான் அறிவேன்; பகைவரை வாட்டுபவனே, நீ அறியாய்.",
        '0.5': "நான் பிறப்பற்றவனும் அழிவற்ற இயல்புடையவனும் எல்லா உயிர்களுக்கும் ஈஸ்வரனுமாக இருந்தும், என் பிரக்ருதியை அடக்கி ஆண்டு, என் ஆத்மமாயையால் (சுய சங்கல்பத்தால்) தோன்றுகிறேன்.",
        '0.6': "பாரதா, எப்போதெல்லாம் தர்மம் குன்றி அதர்மம் தலையெடுக்கிறதோ அப்போதெல்லாம் நான் என்னை வெளிப்படுத்துகிறேன்.",
        '0.7': "நல்லோரைக் காக்கவும் தீயோரை அழிக்கவும் தர்மத்தை நிலைநாட்டவும் நான் யுகந்தோறும் தோன்றுகிறேன்.",
        '0.8': "அர்ஜுனா, என் தெய்வீகப் பிறப்பையும் செயல்களையும் இவ்வாறு உண்மையில் அறிபவன் உடலை நீத்தபின் மீண்டும் பிறப்பதில்லை; என்னையே அடைகிறான்.",
        '0.9': "பற்று, அச்சம், சினம் நீங்கி, என்னில் ஆழ்ந்து, என்னைச் சரணடைந்த பலர் ஞானமென்னும் தவத்தால் தூய்மையடைந்து என் நிலையை அடைந்துள்ளனர்.",
        '0.10': "யார் எந்த விதத்தில் என்னை அணுகுகிறார்களோ அவர்களுக்கு அந்த விதத்திலேயே நான் அருள்கிறேன். பார்த்தா, மனிதர்கள் எல்லா வகையிலும் என் வழியையே பின்பற்றுகின்றனர்.",
        '0.11': "செயல்களின் பலனை விரும்புவோர் இங்கே தேவர்களை வழிபடுகின்றனர்; மனித உலகில் செயலால் வரும் பலன் விரைவில் கிடைக்கிறது.",
        '0.12': "குணம், செயல் ஆகியவற்றின் பிரிவுக்கேற்ப நான்கு வர்ணங்கள் என்னால் படைக்கப்பட்டன. அதற்குக் கர்த்தாவாக இருந்தும் என்னைச் செய்யாதவன், மாறாதவன் என்று அறி.",
        '0.13': "செயல்கள் என்னைத் தீண்டுவதில்லை; செயலின் பலனில் எனக்கு விருப்பமும் இல்லை. இவ்வாறு என்னை அறிபவன் செயல்களால் கட்டுப்படுவதில்லை.",
        '0.14': "இதை அறிந்தே முற்கால முமுக்ஷுக்களும் செயல் புரிந்தனர். ஆகவே முன்னோர் தொன்றுதொட்டுச் செய்தது போல நீயும் செயலையே செய்.",
        '0.15': "செயல் எது, செயலின்மை எது என்பதில் அறிஞர்களும் மயங்குகின்றனர். எதை அறிந்தால் நீ தீமையிலிருந்து விடுபடுவாயோ அந்தச் செயலின் உண்மையை உனக்குச் சொல்வேன்.",
        '0.16': "செயலின் இயல்பையும் விலக்கப்பட்ட செயலின் (விகர்மம்) இயல்பையும் செயலின்மையின் இயல்பையும் அறிய வேண்டும்; செயலின் போக்கு ஆழமானது.",
        '0.17': "செயலில் செயலின்மையையும் செயலின்மையில் செயலையும் காண்பவன் மனிதருள் அறிவாளி; அவனே யோகி, எல்லாச் செயல்களையும் செய்தவன்.",
        '0.18': "யாருடைய எல்லா முயற்சிகளும் ஆசையும் சுயநல எண்ணமும் அற்றவையோ, யாருடைய செயல்கள் ஞானத் தீயில் எரிந்துவிட்டனவோ அவனை அறிஞர்கள் பண்டிதன் என்கின்றனர்.",
        '0.19': "செயல்பலன் மீதான பற்றை விட்டு, எப்போதும் திருப்தியுடன், எதையும் சாராமல் இருப்பவன் செயலில் முழுமையாக ஈடுபட்டிருந்தாலும் எதையும் செய்யாதவனே.",
        '0.20': "ஆசையின்றி, மனத்தையும் உடலையும் அடக்கி, எல்லா உடைமைகளையும் துறந்து, உடலுக்கான செயலை மட்டும் செய்பவன் பாவத்தை அடைவதில்லை.",
        '0.21': "தானாகக் கிடைப்பதில் திருப்தியுற்று, இருமைகளைக் கடந்து, பொறாமையின்றி, வெற்றி தோல்விகளில் சமமாக இருப்பவன் செயல் புரிந்தாலும் கட்டுப்படுவதில்லை.",
        '0.22': "பற்றற்றவனும் விடுபட்டவனும் ஞானத்தில் நிலைத்த மனமுடையவனும் யஜ்ஞத்துக்காகச் செயல்புரிபவனுமான ஒருவனின் எல்லாச் செயல்களும் கரைந்துவிடுகின்றன.",
        '0.23': "அர்ப்பணமே பிரம்மம், ஹவிஸே பிரம்மம், பிரம்மமாகிய அக்னியில் பிரம்மத்தால் இடப்படுகிறது; செயலில் பிரம்மத்தையே தியானிப்பவன் பிரம்மத்தையே அடைகிறான். (மாத்வ விளக்கம்: இங்கே பிரம்மம் என்பது யஜ்ஞத்தின் ஒவ்வோர் அங்கத்திலும் உறையும் விஷ்ணு.)",
        '0.24': "சில யோகிகள் தேவர்களுக்கான யஜ்ஞத்தையே செய்கின்றனர்; வேறு சிலர் பிரம்ம அக்னியில் யஜ்ஞத்தாலேயே யஜ்ஞத்தை ஆகுதியாக்குகின்றனர்.",
        '0.25': "சிலர் செவி முதலிய புலன்களை அடக்கம் என்னும் அக்னிகளில் ஆகுதியாக்குகின்றனர்; வேறு சிலர் ஓசை முதலிய புலனுகர் பொருள்களைப் புலன்கள் என்னும் அக்னிகளில் ஆகுதியாக்குகின்றனர்.",
        '0.26': "வேறு சிலர் புலன்களின் எல்லாச் செயல்களையும் பிராணனின் செயல்களையும் ஞானத்தால் ஒளிரும் தன்னடக்க யோகம் என்னும் அக்னியில் ஆகுதியாக்குகின்றனர்.",
        '0.27': "சிலர் பொருள் யஜ்ஞம், தவ யஜ்ஞம், யோக யஜ்ஞம் செய்கின்றனர்; கடும் விரதமுடைய துறவிகள் வேத ஓதலும் ஞானமுமாகிய யஜ்ஞத்தைச் செய்கின்றனர்.",
        '0.28': "வேறு சிலர் பிராணாயாமத்தில் ஈடுபட்டு, பிராண அபானங்களின் போக்கைத் தடுத்து, அபானத்தில் பிராணனையும் பிராணனில் அபானத்தையும் ஆகுதியாக்குகின்றனர்.",
        '0.29': "சிலர் உணவைக் கட்டுப்படுத்திப் பிராணன்களைப் பிராணன்களில் ஆகுதியாக்குகின்றனர். இவர்கள் அனைவரும் யஜ்ஞத்தை அறிந்தவர்கள்; யஜ்ஞத்தால் இவர்களின் பாவங்கள் அழிந்தன.",
        '0.30': "யஜ்ஞத்தின் மீதியான அமுதத்தை உண்பவர்கள் நிலையான பிரம்மத்தை அடைகின்றனர். குருக்களில் சிறந்தவனே, யஜ்ஞம் செய்யாதவனுக்கு இவ்வுலகமே இல்லை; பின் மறுவுலகம் எங்கே?",
        '0.31': "இவ்வாறு பலவகை யஜ்ஞங்கள் வேதத்தில் விரிவாகக் கூறப்பட்டுள்ளன. அவை அனைத்தும் செயலிலிருந்து பிறந்தவை என்று அறி; இவ்வாறு அறிந்து நீ விடுதலை பெறுவாய்.",
        '0.32': "பகைவரை வாட்டுபவனே, பொருள்களால் ஆன யஜ்ஞத்தைவிட ஞான யஜ்ஞமே மேலானது. பார்த்தா, எல்லாச் செயல்களும் ஞானத்திலேயே நிறைவு பெறுகின்றன.",
        '0.33': "அதைப் பணிவான வணக்கத்தாலும் கேள்விகளாலும் சேவையாலும் அறிந்துகொள். உண்மையைக் கண்ட ஞானியர் உனக்கு அந்த ஞானத்தை உபதேசிப்பார்கள்.",
        '0.34': "பாண்டவா, அதை அறிந்தபின் நீ மீண்டும் இவ்வாறு மயக்கத்தில் விழமாட்டாய்; அதனால் எல்லா உயிர்களையும் உன்னிலும் பின் என்னிலும் காண்பாய்.",
        '0.35': "நீ எல்லாப் பாவிகளிலும் மிகப் பெரும் பாவியாக இருந்தாலும் ஞானம் என்னும் படகாலேயே எல்லாப் பாவங்களையும் கடப்பாய்.",
        '0.36': "அர்ஜுனா, கொழுந்துவிட்டு எரியும் நெருப்பு விறகுகளைச் சாம்பலாக்குவது போல, ஞானத் தீ எல்லாச் செயல்களையும் சாம்பலாக்குகிறது.",
        '0.37': "இவ்வுலகில் ஞானத்துக்கு நிகரான தூய்மைப்படுத்துவது எதுவும் இல்லை. யோகத்தில் நிறைவு பெற்றவன் உரிய காலத்தில் அதைத் தன்னுள்ளே காண்கிறான்.",
        '0.38': "நம்பிக்கை உடையவனும் அதில் ஈடுபாடுள்ளவனும் புலன்களை அடக்கியவனும் ஞானத்தைப் பெறுகிறான்; ஞானத்தைப் பெற்று விரைவில் பரம அமைதியை அடைகிறான்.",
        '0.39': "அறிவில்லாதவனும் நம்பிக்கையற்றவனும் ஐயமுடையவனும் அழிகின்றனர். ஐயமுடையவனுக்கு இவ்வுலகமும் இல்லை, மறுவுலகமும் இல்லை, இன்பமும் இல்லை.",
        '0.40': "தனஞ்ஜயா, யோகத்தால் செயல்களைத் துறந்தவனையும் ஞானத்தால் ஐயங்களை அறுத்தவனையும் தன்னடக்கம் உடையவனையும் செயல்கள் கட்டுவதில்லை.",
        '0.41': "ஆகவே பாரதா, அறியாமையால் பிறந்து இதயத்தில் இருக்கும் இந்த ஐயத்தை ஞானம் என்னும் வாளால் வெட்டி, யோகத்தைச் சார்ந்து எழுந்திரு!",
        '0.42': "ஓம் தத் ஸத். உபநிஷத்தும் பிரம்மவித்யையும் யோகசாஸ்திரமுமான ஸ்ரீமத் பகவத்கீதையில், ஸ்ரீகிருஷ்ண-அர்ஜுன உரையாடலில் \"ஞான கர்ம ஸந்நியாஸ யோகம்\" என்னும் நான்காம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'bhagavad-gita-05': {
      verses: {
        '0.0': "அர்ஜுனன் கூறினான்: கிருஷ்ணா, செயல்களைத் துறப்பதையும் பின் கர்மயோகத்தையும் புகழ்கிறாய். இவ்விரண்டில் எது மேலானதோ அதை உறுதியாகச் சொல்.",
        '0.1': "ஸ்ரீ பகவான் கூறினார்: துறவும் கர்மயோகமும் இரண்டுமே பரம நன்மை தருபவை; ஆனால் இவ்விரண்டில் செயல் துறவைவிடக் கர்மயோகமே மேலானது.",
        '0.2': "யார் வெறுப்பதுமில்லையோ விரும்புவதுமில்லையோ அவனை நித்திய ஸந்நியாசி என்று அறிய வேண்டும்; வலிய தோளனே, இருமைகளற்றவன் எளிதில் தளையிலிருந்து விடுபடுகிறான்.",
        '0.3': "ஸாங்கியமும் யோகமும் வேறு வேறு என்று சிறுபிள்ளைகள் சொல்வர், அறிஞர் அல்லர். ஏதாவது ஒன்றில் சரியாக நிலைத்தவன் இரண்டின் பலனையும் அடைகிறான்.",
        '0.4': "ஸாங்கியர்கள் அடையும் நிலையையே யோகிகளும் அடைகின்றனர். ஸாங்கியத்தையும் யோகத்தையும் ஒன்றாகக் காண்பவனே உண்மையில் காண்பவன்.",
        '0.5': "வலிய தோளனே, யோகம் இன்றித் துறவை அடைவது கடினம்; யோகத்தில் இணைந்த முனிவன் விரைவில் பிரம்மத்தை அடைகிறான்.",
        '0.6': "யோகத்தில் இணைந்தவனும் தூய மனமுடையவனும் தன்னை வென்றவனும் புலன்களை அடக்கியவனும் எல்லா உயிர்களிலும் தன்னைக் காண்பவனுமானவன் செயல் புரிந்தாலும் களங்கமடைவதில்லை.",
        '0.7': "உண்மையை அறிந்த யோகி பார்க்கும்போதும் கேட்கும்போதும் தொடும்போதும் முகரும்போதும் உண்ணும்போதும் நடக்கும்போதும் உறங்கும்போதும் மூச்சுவிடும்போதும் \"நான் எதையும் செய்யவில்லை\" என்று எண்ணுகிறான்,",
        '0.8': "பேசும்போதும் விடும்போதும் பற்றும்போதும் கண்களைத் திறந்து மூடும்போதும் \"புலன்கள் தம் பொருள்களில் இயங்குகின்றன\" என்று உறுதியாகக் கொள்கிறான்.",
        '0.9': "செயல்களைப் பிரம்மத்துக்கு (பரமாத்மாவுக்கு) அர்ப்பணித்துப் பற்றைவிட்டுச் செயல்புரிபவன், நீரால் தாமரை இலை போல, பாவத்தால் தீண்டப்படுவதில்லை.",
        '0.10': "யோகிகள் பற்றைவிட்டு உடல், மனம், அறிவு, புலன்கள் ஆகியவற்றால் மட்டும் தம்மைத் தூய்மைப்படுத்திக்கொள்ளச் செயல் புரிகின்றனர்.",
        '0.11': "யோகத்தில் இணைந்தவன் செயல்பலனைத் துறந்து நிலையான அமைதியை அடைகிறான்; இணையாதவன் ஆசையால் தூண்டப்பட்டுப் பலனில் பற்றுக்கொண்டு கட்டுப்படுகிறான்.",
        '0.12': "மனத்தால் எல்லாச் செயல்களையும் துறந்து, தன்னடக்கமுள்ள ஆத்மா ஒன்பது வாயில்களுடைய நகரில் (உடலில்) செய்யாமலும் செய்விக்காமலும் இன்பமாக வாழ்கிறது.",
        '0.13': "இறைவன் உலகுக்குச் செய்பவன் என்ற தன்மையையோ செயல்களையோ செயலுக்கும் பலனுக்குமான தொடர்பையோ படைப்பதில்லை; இயல்பே (ஸ்வபாவம்) செயல்படுகிறது.",
        '0.14': "எங்கும் நிறைந்த இறைவன் யாருடைய பாவத்தையும் புண்ணியத்தையும் ஏற்பதில்லை. அறியாமையால் அறிவு மறைக்கப்பட்டுள்ளது; அதனால் உயிர்கள் மயங்குகின்றன.",
        '0.15': "ஆனால் யாருடைய அறியாமை ஆத்ம ஞானத்தால் அழிக்கப்பட்டதோ, அவர்களுடைய அந்த ஞானம் சூரியனைப் போலப் பரம்பொருளை ஒளிரச் செய்கிறது.",
        '0.16': "அதிலேயே அறிவைச் செலுத்தி, அதிலேயே மனத்தைச் செலுத்தி, அதிலேயே நிலைத்து, அதையே புகலிடமாகக் கொண்டு, ஞானத்தால் பாவங்களைக் கழுவியவர்கள் மீண்டும் திரும்பாத நிலையை அடைகின்றனர்.",
        '0.17': "கல்வியும் பணிவும் நிறைந்த பிராம்மணனிடமும் பசுவிடமும் யானையிடமும் நாயிடமும் நாயுண்ணியிடமும் அறிஞர்கள் சம நோக்குடையவர்கள்.",
        '0.18': "யாருடைய மனம் சமநிலையில் நிலைத்துள்ளதோ அவர்கள் இங்கேயே பிறவியை வென்றுவிட்டனர். பிரம்மம் குறையற்றது, எல்லாவற்றிலும் சமமானது; ஆகவே அவர்கள் பிரம்மத்தில் நிலைத்துள்ளனர்.",
        '0.19': "விரும்பியது கிடைத்தால் களிக்கக்கூடாது; விரும்பாதது கிடைத்தால் கலங்கக்கூடாது. நிலைத்த அறிவுடைய, மயக்கமற்ற பிரம்மஞானி பிரம்மத்தில் நிலைத்திருக்கிறான்.",
        '0.20': "வெளிப்புறத் தொடர்புகளில் பற்றில்லாதவன் ஆத்மாவில் உள்ள இன்பத்தை அடைகிறான்; பிரம்ம யோகத்தில் இணைந்த அவன் அழியாத இன்பத்தை அனுபவிக்கிறான்.",
        '0.21': "குந்தியின் மகனே, தொடர்பால் பிறக்கும் இன்பங்கள் துன்பத்தின் பிறப்பிடங்களே; அவை தொடக்கமும் முடிவும் உடையவை. அறிஞன் அவற்றில் மகிழ்வதில்லை.",
        '0.22': "உடலை விடுவதற்கு முன்பே இங்கேயே ஆசையாலும் சினத்தாலும் எழும் வேகத்தைத் தாங்க வல்லவனே யோகி; அவனே இன்பமுடையவன்.",
        '0.23': "உள்ளேயே இன்பமுடையவனும் உள்ளேயே மகிழ்பவனும் உள்ளேயே ஒளியுடையவனுமான அந்த யோகி பிரம்ம நிலையடைந்து பிரம்ம நிர்வாணத்தை அடைகிறான்.",
        '0.24': "பாவங்கள் நீங்கியவர்களும் ஐயங்கள் அறுபட்டவர்களும் தன்னடக்கம் உடையவர்களும் எல்லா உயிர்களின் நலனில் ஈடுபட்டவர்களுமான ரிஷிகள் பிரம்ம நிர்வாணத்தை அடைகின்றனர்.",
        '0.25': "ஆசையும் சினமும் நீங்கி, மனத்தை அடக்கி, ஆத்மாவை அறிந்த துறவிகளுக்கு எல்லாப் புறமும் பிரம்ம நிர்வாணம் அருகிலேயே உள்ளது.",
        '0.26': "வெளிப்புறத் தொடர்புகளை வெளியிலேயே விலக்கி, பார்வையைப் புருவங்களின் நடுவே நிறுத்தி, நாசிக்குள் இயங்கும் பிராண அபானங்களைச் சமமாக்கி,",
        '0.27': "புலன்கள், மனம், அறிவு ஆகியவற்றை அடக்கியவனும் மோக்ஷத்தையே இலக்காகக் கொண்டவனும் விருப்பு, அச்சம், சினம் நீங்கியவனுமான முனிவன் என்றும் விடுபட்டவனே.",
        '0.28': "யஜ்ஞங்களையும் தவங்களையும் அனுபவிப்பவனும், எல்லா உலகங்களுக்கும் மகேஸ்வரனும், எல்லா உயிர்களுக்கும் நண்பனுமான என்னை அறிந்தவன் அமைதியை அடைகிறான்.",
        '0.29': "ஓம் தத் ஸத். உபநிஷத்தும் பிரம்மவித்யையும் யோகசாஸ்திரமுமான ஸ்ரீமத் பகவத்கீதையில், ஸ்ரீகிருஷ்ண-அர்ஜுன உரையாடலில் \"கர்ம ஸந்நியாஸ யோகம்\" என்னும் ஐந்தாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'bhagavad-gita-06': {
      verses: {
        '0.0': "ஸ்ரீ பகவான் கூறினார்: செயல்பலனைச் சாராமல் செய்ய வேண்டிய செயலைச் செய்பவனே ஸந்நியாசி, அவனே யோகி; வெறுமனே அக்னியைத் துறந்தவனோ சடங்குகளைத் துறந்தவனோ அல்லன்.",
        '0.1': "பாண்டவா, எதைத் துறவு என்கிறார்களோ அதையே யோகம் என்று அறி; சுயநல எண்ணங்களைத் (ஸங்கல்பம்) துறக்காதவன் யாரும் யோகியாக முடியாது.",
        '0.2': "யோகத்தில் ஏற விரும்பும் முனிவனுக்குச் செயலே வழி எனப்படுகிறது; யோகத்தில் ஏறிவிட்ட அவனுக்கே அமைதியே வழி எனப்படுகிறது.",
        '0.3': "புலனுகர் பொருள்களிலோ செயல்களிலோ பற்றுக்கொள்ளாமல், எல்லா ஸங்கல்பங்களையும் துறந்தவனாக இருக்கும்போது ஒருவன் யோகத்தில் ஏறியவன் எனப்படுகிறான்.",
        '0.4': "தன்னைத் தானே உயர்த்திக்கொள்ள வேண்டும்; தன்னைத் தாழ விடக்கூடாது; ஒருவனுக்குத் தானே நண்பன், தானே பகைவன்.",
        '0.5': "யார் தன்னால் தன்னை வென்றானோ அவனுக்குத் தானே நண்பன்; தன்னை வெல்லாதவனுக்குத் தானே பகைவன் போலப் பகைமையில் நடக்கிறான்.",
        '0.6': "தன்னை வென்று அமைதியுற்றவனுக்குக் குளிர்-வெப்பம், இன்பம்-துன்பம், மானம்-அவமானம் ஆகியவற்றிலும் பரமாத்மா நிலையாக அருகில் இருக்கிறார்.",
        '0.7': "ஞானத்தாலும் விஞ்ஞானத்தாலும் திருப்தியுற்றவனும் அசையாதவனும் புலன்களை வென்றவனும் மண்கட்டி, கல், பொன் ஆகியவற்றைச் சமமாகக் கருதுபவனுமான யோகி இணைந்தவன் எனப்படுகிறான்.",
        '0.8': "நலம் விரும்பிகள், நண்பர்கள், பகைவர்கள், பாராமுகர்கள், நடுநிலையாளர்கள், வெறுக்கத்தக்கவர்கள், உறவினர்கள், நல்லோர், தீயோர் ஆகிய அனைவரிடமும் சம அறிவுடையவன் சிறந்தவன்.",
        '0.9': "யோகி தனிமையான இடத்தில் தனித்திருந்து, மனத்தையும் உடலையும் அடக்கி, ஆசையும் உடைமையுமின்றி இடைவிடாமல் மனத்தை ஒருமுகப்படுத்த வேண்டும்.",
        '0.10': "தூய இடத்தில், மிக உயரமும் இல்லாத மிகத் தாழ்வும் இல்லாத, தர்ப்பை, மான்தோல், துணி ஆகியவை விரிக்கப்பட்ட உறுதியான ஆசனத்தை அமைத்து,",
        '0.11': "அங்கே அந்த ஆசனத்தில் அமர்ந்து, மனத்தை ஒருமுகப்படுத்தி, மனம் மற்றும் புலன்களின் இயக்கத்தை அடக்கி, தன்னைத் தூய்மைப்படுத்த யோகம் பயில வேண்டும்.",
        '0.12': "உடல், தலை, கழுத்து ஆகியவற்றை நேராகவும் அசையாமலும் வைத்து, நிலையாக, தன் மூக்கின் நுனியை நோக்கி, திசைகளைப் பார்க்காமல்,",
        '0.13': "அமைதியான மனத்துடன், அச்சமின்றி, பிரம்மசரிய விரதத்தில் நிலைத்து, மனத்தை அடக்கி, என்னிடம் சித்தத்தைச் செலுத்தி, என்னையே பரமாகக் கொண்டு யோகத்தில் அமர வேண்டும்.",
        '0.14': "இவ்வாறு எப்போதும் தன்னை யோகத்தில் இணைக்கும், மனத்தை அடக்கிய யோகி என்னில் நிலைத்திருக்கும், நிர்வாணத்தையே உச்சமாகக் கொண்ட அமைதியை அடைகிறான்.",
        '0.15': "அர்ஜுனா, அளவுக்கு மீறி உண்பவனுக்கும் யோகம் இல்லை; உண்ணாமலே இருப்பவனுக்கும் இல்லை; மிக அதிகம் உறங்குபவனுக்கும் இல்லை; மிக அதிகம் விழித்திருப்பவனுக்கும் இல்லை.",
        '0.16': "அளவான உணவும் பொழுதுபோக்கும், செயல்களில் அளவான முயற்சியும், அளவான உறக்கமும் விழிப்பும் உடையவனுக்கு யோகம் துன்பத்தை அழிப்பதாகிறது.",
        '0.17': "நன்கு அடக்கப்பட்ட மனம் ஆத்மாவிலேயே நிலைக்கும்போது, எல்லா ஆசைகளிலும் ஏக்கமற்றவனாகும்போது அவன் இணைந்தவன் (யுக்தன்) எனப்படுகிறான்.",
        '0.18': "\"காற்றில்லாத இடத்தில் உள்ள விளக்கு அசைவதில்லை\" — மனத்தை அடக்கி ஆத்ம யோகம் பயிலும் யோகிக்கு இதுவே உவமை எனப்படுகிறது.",
        '0.19': "யோகப் பயிற்சியால் அடக்கப்பட்ட மனம் எங்கே ஓய்வடைகிறதோ, எங்கே தன்னால் தன்னைக் கண்டு தன்னிலேயே மகிழ்கிறானோ,",
        '0.20': "எங்கே அறிவால் மட்டும் அறியக்கூடியதும் புலன்களுக்கு அப்பாற்பட்டதுமான எல்லையற்ற இன்பத்தை உணர்கிறானோ, எங்கே நிலைத்து உண்மையிலிருந்து ஒருபோதும் விலகுவதில்லையோ,",
        '0.21': "எதைப் பெற்றபின் அதைவிடப் பெரிய பேறு வேறில்லை என்று கருதுகிறானோ, எதில் நிலைத்தவன் பெருந்துன்பத்தாலும் அசைக்கப்படுவதில்லையோ —",
        '0.22': "துன்பத்தோடுள்ள தொடர்பிலிருந்து விடுபடும் அந்த நிலையே யோகம் என்று அறி. அந்த யோகத்தை உறுதியுடனும் சோர்வற்ற மனத்துடனும் பயில வேண்டும்.",
        '0.23': "ஸங்கல்பத்தால் பிறக்கும் எல்லா ஆசைகளையும் முழுமையாகத் துறந்து, மனத்தாலேயே புலன்களின் கூட்டத்தை எல்லாப் புறமும் அடக்கி,",
        '0.24': "உறுதியால் பற்றப்பட்ட அறிவால் மெல்ல மெல்ல அமைதியடைய வேண்டும்; மனத்தை ஆத்மாவில் நிலைநிறுத்தி வேறு எதையும் எண்ணக்கூடாது.",
        '0.25': "அலைபாயும் நிலையற்ற மனம் எங்கெங்கே செல்கிறதோ அங்கங்கிருந்து அதை இழுத்து ஆத்மாவிலேயே வசப்படுத்த வேண்டும்.",
        '0.26': "அமைதியான மனமுடைய, ரஜோகுணம் தணிந்த, பிரம்ம நிலையடைந்த, பாவமற்ற இந்த யோகியை உயர்ந்த இன்பம் வந்தடைகிறது.",
        '0.27': "இவ்வாறு எப்போதும் தன்னை யோகத்தில் இணைக்கும் பாவமற்ற யோகி எளிதில் பிரம்மத்தோடு தொடர்பு கொள்ளும் எல்லையற்ற இன்பத்தை அனுபவிக்கிறான்.",
        '0.28': "யோகத்தில் இணைந்து எங்கும் சம நோக்குடையவன் எல்லா உயிர்களிலும் உள்ள ஆத்மாவையும் ஆத்மாவில் உள்ள எல்லா உயிர்களையும் காண்கிறான்.",
        '0.29': "யார் என்னை எங்கும் காண்கிறானோ, எல்லாவற்றையும் என்னில் காண்கிறானோ, அவனுக்கு நான் மறைவதில்லை; அவனும் எனக்கு மறைவதில்லை.",
        '0.30': "ஒருமை நிலையில் நின்று எல்லா உயிர்களிலும் உறையும் என்னை வழிபடும் யோகி எவ்வாறு வாழ்ந்தாலும் என்னிலேயே வாழ்கிறான்.",
        '0.31': "அர்ஜுனா, தன்னோடு ஒப்பிட்டு, இன்பமோ துன்பமோ எல்லாவற்றிலும் சமமாகக் காண்பவனே உயர்ந்த யோகி என்பது என் கருத்து.",
        '0.32': "அர்ஜுனன் கூறினான்: மதுசூதனா, நீ உரைத்த இந்தச் சமநிலை யோகத்துக்கு, மனத்தின் சஞ்சலத்தால், நிலையான நிலைப்பை நான் காணவில்லை.",
        '0.33': "கிருஷ்ணா, மனம் அலைபாய்வது, கலக்குவது, வலிமையானது, பிடிவாதமானது. அதை அடக்குவது காற்றை அடக்குவது போல மிகக் கடினம் என்று நினைக்கிறேன்.",
        '0.34': "ஸ்ரீ பகவான் கூறினார்: வலிய தோளனே, மனம் அலைபாய்வது, அடக்குவதற்குக் கடினமானது என்பதில் ஐயமில்லை; ஆனால் குந்தியின் மகனே, பயிற்சியாலும் வைராக்கியத்தாலும் அது வசப்படுகிறது.",
        '0.35': "மனத்தை அடக்காதவனுக்கு யோகம் அடைவதற்கு அரியது என்பது என் கருத்து; மனத்தை அடக்கி உரிய வழியில் முயல்பவன் அதை அடைய முடியும்.",
        '0.36': "அர்ஜுனன் கூறினான்: கிருஷ்ணா, நம்பிக்கை இருந்தும் போதிய முயற்சி இல்லாதவன், யோகத்திலிருந்து மனம் வழுவியவன், யோக சித்தியை அடையாமல் எந்த நிலையை அடைகிறான்?",
        '0.37': "வலிய தோளனே, இரண்டிலிருந்தும் வழுவி, ஆதாரமின்றி, பிரம்ம வழியில் மயங்கியவன் சிதறிய மேகம் போல அழிந்துவிட மாட்டானா?",
        '0.38': "கிருஷ்ணா, என் இந்த ஐயத்தை நீ முழுமையாகப் போக்க வேண்டும்; உன்னைத் தவிர இந்த ஐயத்தைப் போக்கக்கூடியவர் வேறு யாரும் இல்லை.",
        '0.39': "ஸ்ரீ பகவான் கூறினார்: பார்த்தா, அவனுக்கு இம்மையிலும் அழிவில்லை, மறுமையிலும் அழிவில்லை; அன்பனே, நன்மை செய்பவன் யாரும் தீய கதியை அடைவதில்லை.",
        '0.40': "யோகத்திலிருந்து வழுவியவன் புண்ணியவான்களின் உலகங்களை அடைந்து அங்கே பல ஆண்டுகள் வாழ்ந்து, தூயவர்களும் செல்வர்களுமானவர்களின் வீட்டில் பிறக்கிறான்.",
        '0.41': "அல்லது அறிவுமிக்க யோகிகளின் குலத்திலேயே பிறக்கிறான்; இத்தகைய பிறவி இவ்வுலகில் மிக அரிது.",
        '0.42': "அங்கே அவன் முந்தைய உடலில் பெற்ற அறிவுத் தொடர்பை மீண்டும் பெறுகிறான்; குருநந்தனா, அங்கிருந்து மீண்டும் சித்திக்காக முயல்கிறான்.",
        '0.43': "அந்த முந்தைய பயிற்சியாலேயே அவன் தன்வசமின்றியும் ஈர்க்கப்படுகிறான். யோகத்தை அறிய விரும்புபவனும் சப்த பிரம்மத்தை (வேதச் சடங்குகளின் பலனை) கடந்து செல்கிறான்.",
        '0.44': "ஆனால் விடாமுயற்சியுடன் பயிலும் யோகி பாவங்களிலிருந்து தூய்மையடைந்து, பல பிறவிகளில் நிறைவு பெற்று, பின்னர் பரம கதியை அடைகிறான்.",
        '0.45': "யோகி தவசிகளைவிட மேலானவன்; நூலறிவாளர்களைவிடவும் மேலானவனாகக் கருதப்படுகிறான்; சடங்குகள் செய்பவர்களைவிடவும் மேலானவன். ஆகவே அர்ஜுனா, நீ யோகியாகு.",
        '0.46': "எல்லா யோகிகளிலும், யார் என்னில் ஆழ்ந்த உள்ளத்துடன் நம்பிக்கையோடு என்னை வழிபடுகிறானோ அவனே மிகச் சிறந்த யோகி என்பது என் கருத்து.",
        '0.47': "ஓம் தத் ஸத். உபநிஷத்தும் பிரம்மவித்யையும் யோகசாஸ்திரமுமான ஸ்ரீமத் பகவத்கீதையில், ஸ்ரீகிருஷ்ண-அர்ஜுன உரையாடலில் \"ஆத்ம ஸம்யம யோகம்\" என்னும் ஆறாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'bhagavad-gita-07': {
      verses: {
        '0.0': "ஸ்ரீ பகவான் கூறினார்: பார்த்தா, என்னிடம் பற்றுக்கொண்ட மனத்துடன், என்னைச் சார்ந்து யோகம் பயின்று, நீ என்னை ஐயமின்றி முழுமையாக எவ்வாறு அறிவாய் என்பதைக் கேள்.",
        '0.1': "எதை அறிந்தபின் இங்கே அறிய வேண்டியது வேறெதுவும் எஞ்சாதோ அந்த விஞ்ஞானத்துடன் கூடிய ஞானத்தை நான் உனக்கு முழுமையாகச் சொல்வேன்.",
        '0.2': "ஆயிரக்கணக்கான மனிதர்களில் யாரோ ஒருவன் சித்திக்காக முயல்கிறான்; முயன்று சித்தியடைந்தவர்களிலும் யாரோ ஒருவனே என்னை உண்மையில் அறிகிறான்.",
        '0.3': "நிலம், நீர், நெருப்பு, காற்று, ஆகாயம், மனம், அறிவு, அகங்காரம் — இது எட்டு வகையாகப் பிரிந்த என் பிரக்ருதி.",
        '0.4': "இது தாழ்ந்த பிரக்ருதி. வலிய தோளனே, இதனின் வேறான, உயிர் வடிவமான என் உயர்ந்த பிரக்ருதியை அறி; அதனாலேயே இவ்வுலகம் தாங்கப்படுகிறது.",
        '0.5': "எல்லா உயிர்களும் இவ்விரண்டையும் பிறப்பிடமாகக் கொண்டவை என்று உணர். முழு உலகத்தின் தோற்றமும் ஒடுக்கமும் நானே.",
        '0.6': "தனஞ்ஜயா, என்னைவிட உயர்ந்தது வேறு எதுவும் இல்லை. நூலில் மணிகள் போல இவையனைத்தும் என்னில் கோக்கப்பட்டுள்ளன.",
        '0.7': "குந்தியின் மகனே, நீரில் சுவை நான்; சந்திர சூரியர்களில் ஒளி நான்; எல்லா வேதங்களிலும் ஓங்காரம்; ஆகாயத்தில் ஓசை; மனிதர்களில் ஆண்மை நான்.",
        '0.8': "மண்ணில் தூய மணம் நான்; நெருப்பில் ஒளி நான்; எல்லா உயிர்களிலும் உயிர்ப்பு நான்; தவசிகளில் தவம் நான்.",
        '0.9': "பார்த்தா, என்னை எல்லா உயிர்களின் நிலையான விதை என்று அறி. அறிவாளிகளின் அறிவு நான்; ஒளியுடையவர்களின் ஒளி நான்.",
        '0.10': "வலிமையுடையவர்களில் ஆசையும் பற்றும் அற்ற வலிமை நான்; பரதர்களில் சிறந்தவனே, உயிர்களில் தர்மத்துக்கு முரணில்லாத விருப்பம் நான்.",
        '0.11': "ஸாத்விக, ராஜஸ, தாமஸ இயல்புகள் எவை உண்டோ அவை அனைத்தும் என்னிடமிருந்தே என்று அறி; ஆனால் நான் அவற்றில் இல்லை; அவை என்னில் உள்ளன.",
        '0.12': "குணங்களாலான இந்த மூன்று இயல்புகளால் மயங்கிய இவ்வுலகம் முழுவதும் இவற்றுக்கு அப்பாற்பட்ட, அழிவற்ற என்னை அறிவதில்லை.",
        '0.13': "குணங்களாலான என் இந்தத் தெய்வீக மாயை கடப்பதற்கு அரியது; என்னையே சரணடைபவர்கள் இந்த மாயையைக் கடக்கின்றனர்.",
        '0.14': "தீவினையாளர்களும் மூடர்களும் மனிதருள் இழிந்தவர்களும், மாயையால் அறிவு கவரப்பட்டு அசுர இயல்பைச் சார்ந்தவர்களும் என்னைச் சரணடைவதில்லை.",
        '0.15': "அர்ஜுனா, நான்கு வகை நல்வினையாளர்கள் என்னை வழிபடுகின்றனர்: துன்புற்றவன், அறிய விரும்புபவன், பொருள் விரும்புபவன், ஞானி — பரதர்களில் சிறந்தவனே.",
        '0.16': "அவர்களில் எப்போதும் இணைந்திருப்பவனும் ஒருவனிடமே பக்தி கொண்டவனுமான ஞானியே சிறந்தவன். ஞானிக்கு நான் மிகவும் பிரியமானவன்; அவனும் எனக்குப் பிரியமானவன்.",
        '0.17': "இவர்கள் அனைவரும் உயர்ந்தவர்களே; ஆனால் ஞானி என் ஆத்மாவே என்பது என் கருத்து; ஏனெனில் இணைந்த மனமுடைய அவன் உன்னத இலக்கான என்னிலேயே நிலைத்திருக்கிறான்.",
        '0.18': "பல பிறவிகளின் முடிவில் ஞானி \"வாஸுதேவனே எல்லாம்\" என்று உணர்ந்து என்னைச் சரணடைகிறான். அத்தகைய மகாத்மா மிக அரியவன்.",
        '0.19': "பல்வேறு ஆசைகளால் அறிவு கவரப்பட்டவர்கள் தம் இயல்புக்குக் கட்டுப்பட்டு, அந்தந்த நியமங்களைக் கடைப்பிடித்துப் பிற தேவதைகளைச் சரணடைகின்றனர்.",
        '0.20': "எந்த எந்த பக்தன் எந்த எந்த வடிவத்தை நம்பிக்கையுடன் வழிபட விரும்புகிறானோ, அவனுடைய அந்த நம்பிக்கையையே நான் அசையாததாக்குகிறேன்.",
        '0.21': "அந்த நம்பிக்கையுடன் அவன் அத்தேவதையை வழிபடுகிறான்; அதனால் தன் விருப்பங்களைப் பெறுகிறான் — ஆனால் அவற்றை அருள்பவன் நானே.",
        '0.22': "ஆனால் சிற்றறிவுடைய அவர்கள் பெறும் பலன் முடிவுடையது. தேவர்களை வழிபடுவோர் தேவர்களை அடைகின்றனர்; என் பக்தர்கள் என்னையே அடைகின்றனர்.",
        '0.23': "அறிவற்றவர்கள் வெளிப்படாத என்னை வெளிப்பட்டவனாக (சாதாரண உடலுடையவனாக) எண்ணுகின்றனர்; அழிவற்றதும் உன்னதமானதுமான என் பரம இயல்பை அவர்கள் அறியார்.",
        '0.24': "யோகமாயையால் மறைக்கப்பட்ட நான் எல்லாருக்கும் வெளிப்படுவதில்லை. மயங்கிய இவ்வுலகம் பிறப்பற்ற, அழிவற்ற என்னை அறிவதில்லை.",
        '0.25': "அர்ஜுனா, கடந்த, நிகழ்கின்ற, வரப்போகும் உயிர்கள் அனைத்தையும் நான் அறிவேன்; ஆனால் என்னை யாரும் அறியார்.",
        '0.26': "பகைவரை வாட்டும் பாரதா, விருப்பு வெறுப்பால் எழும் இருமை மயக்கத்தால் எல்லா உயிர்களும் பிறக்கும்போதே மயக்கத்தில் விழுகின்றன.",
        '0.27': "ஆனால் யாருடைய பாவம் முடிவுக்கு வந்ததோ அந்த நல்வினையாளர்கள் இருமை மயக்கத்திலிருந்து விடுபட்டு உறுதியான விரதத்துடன் என்னை வழிபடுகின்றனர்.",
        '0.28': "மூப்பு, இறப்பிலிருந்து விடுபட என்னைச் சார்ந்து முயல்பவர்கள் அந்தப் பிரம்மத்தையும் முழு அத்யாத்மத்தையும் எல்லாக் கர்மத்தையும் அறிகின்றனர்.",
        '0.29': "அதிபூதம், அதிதைவம், அதியஜ்ஞம் ஆகியவற்றுடன் என்னை அறிந்தவர்கள், இணைந்த மனத்துடன், உயிர் பிரியும் வேளையிலும் என்னை அறிகின்றனர்.",
        '0.30': "ஓம் தத் ஸத். உபநிஷத்தும் பிரம்மவித்யையும் யோகசாஸ்திரமுமான ஸ்ரீமத் பகவத்கீதையில், ஸ்ரீகிருஷ்ண-அர்ஜுன உரையாடலில் \"ஞான விஞ்ஞான யோகம்\" என்னும் ஏழாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'bhagavad-gita-08': {
      verses: {
        '0.0': "அர்ஜுனன் கூறினான்: புருஷோத்தமா, அந்தப் பிரம்மம் எது? அத்யாத்மம் எது? கர்மம் எது? அதிபூதம் என்று எது சொல்லப்படுகிறது? அதிதைவம் என்று எது அழைக்கப்படுகிறது?",
        '0.1': "மதுசூதனா, இந்த உடலில் அதியஜ்ஞன் யார், எப்படி? தன்னடக்கமுடையவர்களால் இறுதிக் காலத்தில் நீ எப்படி அறியப்படுவாய்?",
        '0.2': "ஸ்ரீ பகவான் கூறினார்: அழிவற்ற பரம்பொருளே பிரம்மம்; தன் இயல்பு (ஸ்வபாவம்) அத்யாத்மம் எனப்படுகிறது; உயிர்களைத் தோற்றுவிக்கும் அர்ப்பணம் (விஸர்க்கம்) கர்மம் எனப்படுகிறது.",
        '0.3': "அழியும் பொருள்களே அதிபூதம்; புருஷனே அதிதைவம்; உடலுடையவர்களில் சிறந்தவனே, இந்த உடலில் அதியஜ்ஞன் நானே.",
        '0.4': "இறுதிக் காலத்தில் என்னையே நினைத்துக்கொண்டு உடலை விட்டுச் செல்பவன் என் நிலையை அடைகிறான்; இதில் ஐயமில்லை.",
        '0.5': "குந்தியின் மகனே, இறுதியில் எந்த எந்த நிலையை நினைத்துக்கொண்டு உடலை விடுகிறானோ, எப்போதும் அதிலேயே ஆழ்ந்திருந்த அவன் அதையே அடைகிறான்.",
        '0.6': "ஆகவே எல்லாக் காலங்களிலும் என்னை நினை, போரும் செய். மனத்தையும் அறிவையும் எனக்கு அர்ப்பணித்த நீ ஐயமின்றி என்னையே அடைவாய்.",
        '0.7': "பார்த்தா, பயிற்சி யோகத்தால் இணைந்த, வேறிடம் செல்லாத மனத்துடன் இடைவிடாமல் தியானிப்பவன் தெய்வீகமான பரம புருஷனை அடைகிறான்.",
        '0.8': "முற்றும் அறிந்தவனும் தொன்மையானவனும் ஆள்பவனும் அணுவினும் நுண்ணியவனும் எல்லாவற்றையும் தாங்குபவனும் சிந்தனைக்கு எட்டாத வடிவினனும் சூரியனைப் போல் ஒளிர்பவனும் இருளுக்கு அப்பாற்பட்டவனுமான அவனை நினைப்பவன் —",
        '0.9': "உயிர் பிரியும் வேளையில் அசையாத மனத்துடன், பக்தியும் யோக வலிமையும் கொண்டு, பிராணனைப் புருவங்களின் நடுவே சரியாக நிறுத்தி, அந்தத் தெய்வீகப் பரம புருஷனை அடைகிறான்.",
        '0.10': "வேதம் அறிந்தோர் எதை அழிவற்றது என்கிறார்களோ, பற்றற்ற துறவிகள் எதில் புகுகிறார்களோ, எதை விரும்பிப் பிரம்மசரியம் காக்கிறார்களோ அந்த நிலையை உனக்குச் சுருக்கமாகச் சொல்வேன்.",
        '0.11': "புலன்களின் எல்லா வாயில்களையும் அடைத்து, மனத்தை இதயத்தில் நிறுத்தி, தன் பிராணனைத் தலையில் நிலைநிறுத்தி, யோக தாரணையில் நிலைத்து,",
        '0.12': "\"ஓம்\" என்னும் ஓரெழுத்துப் பிரம்மத்தை உச்சரித்து, என்னை நினைத்துக்கொண்டு உடலை விட்டுச் செல்பவன் பரம கதியை அடைகிறான்.",
        '0.13': "பார்த்தா, வேறு எண்ணமின்றி இடைவிடாமல் நாள்தோறும் என்னை நினைக்கும், எப்போதும் இணைந்திருக்கும் யோகிக்கு நான் எளிதில் கிடைப்பவன்.",
        '0.14': "என்னை அடைந்து உன்னத சித்தி பெற்ற மகாத்மாக்கள் துன்பத்தின் உறைவிடமும் நிலையற்றதுமான மறுபிறவியை அடைவதில்லை.",
        '0.15': "அர்ஜுனா, பிரம்மலோகம் வரையிலான எல்லா உலகங்களும் மீண்டு வருதலுக்கு உட்பட்டவை; ஆனால் குந்தியின் மகனே, என்னை அடைந்தால் மறுபிறவி இல்லை.",
        '0.16': "ஆயிரம் யுகங்கள் கொண்டது பிரம்மாவின் ஒரு பகல், ஆயிரம் யுகங்கள் கொண்டது அவரது இரவு என்று அறிந்தவர்களே பகலையும் இரவையும் அறிந்தவர்கள்.",
        '0.17': "பகல் தொடங்கும்போது வெளிப்படாததிலிருந்து எல்லா வெளிப்பட்டவையும் தோன்றுகின்றன; இரவு வரும்போது வெளிப்படாதது எனப்படும் அதிலேயே ஒடுங்குகின்றன.",
        '0.18': "பார்த்தா, இதே உயிர்க்கூட்டம் மீண்டும் மீண்டும் தோன்றி, இரவு வரும்போது தன்வசமின்றி ஒடுங்குகிறது; பகல் வரும்போது மீண்டும் தோன்றுகிறது.",
        '0.19': "ஆனால் அந்த வெளிப்படாததற்கும் அப்பால் வேறொரு நிலையான வெளிப்படாத இருப்பு உள்ளது; எல்லா உயிர்களும் அழியும்போதும் அது அழிவதில்லை.",
        '0.20': "அந்த வெளிப்படாதது அழிவற்றது எனப்படுகிறது; அதுவே பரம கதி எனப்படுகிறது. அதை அடைந்தவர்கள் திரும்புவதில்லை; அதுவே என் உன்னத இருப்பிடம்.",
        '0.21': "பார்த்தா, யாருக்குள் எல்லா உயிர்களும் உள்ளனவோ, யாரால் இவையனைத்தும் வியாபிக்கப்பட்டுள்ளதோ அந்தப் பரம புருஷன் வேறு நாட்டமில்லாத பக்தியால் மட்டுமே அடையத்தக்கவன்.",
        '0.22': "பரதர்களில் சிறந்தவனே, எந்தக் காலத்தில் பிரியும் யோகிகள் திரும்பாத நிலையையும், எந்தக் காலத்தில் பிரிபவர்கள் திரும்பும் நிலையையும் அடைகிறார்களோ அந்தக் காலத்தைச் சொல்வேன்.",
        '0.23': "அக்னி, ஒளி, பகல், வளர்பிறை, உத்தராயணத்தின் ஆறு மாதங்கள் — இந்த வழியில் செல்லும் பிரம்மஞானிகள் பிரம்மத்தை அடைகின்றனர்.",
        '0.24': "புகை, இரவு, தேய்பிறை, தட்சிணாயனத்தின் ஆறு மாதங்கள் — இந்த வழியில் செல்லும் யோகி சந்திர ஒளியை அடைந்து திரும்புகிறான்.",
        '0.25': "உலகின் இந்த ஒளி, இருள் ஆகிய இரு வழிகளும் நிலையானவை எனக் கருதப்படுகின்றன. ஒன்றால் திரும்பாத நிலையை அடைகிறான்; மற்றொன்றால் மீண்டும் திரும்புகிறான்.",
        '0.26': "பார்த்தா, இவ்விரு வழிகளையும் அறிந்த எந்த யோகியும் மயங்குவதில்லை. ஆகவே அர்ஜுனா, எல்லாக் காலங்களிலும் யோகத்தில் இணைந்தவனாக இரு.",
        '0.27': "வேதங்கள், யஜ்ஞங்கள், தவங்கள், தானங்கள் ஆகியவற்றுக்கு எந்தப் புண்ணியப் பலன் கூறப்பட்டுள்ளதோ, இதை அறிந்த யோகி அவை அனைத்தையும் கடந்து ஆதியான உன்னத இடத்தை அடைகிறான்.",
        '0.28': "ஓம் தத் ஸத். உபநிஷத்தும் பிரம்மவித்யையும் யோகசாஸ்திரமுமான ஸ்ரீமத் பகவத்கீதையில், ஸ்ரீகிருஷ்ண-அர்ஜுன உரையாடலில் \"அக்ஷர பிரம்ம யோகம்\" என்னும் எட்டாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'bhagavad-gita-09': {
      verses: {
        '0.0': "ஸ்ரீ பகவான் கூறினார்: குறை காணாத உனக்கு மிக ரகசியமான இந்த விஞ்ஞானத்துடன் கூடிய ஞானத்தை உரைப்பேன்; இதை அறிந்து நீ தீமையிலிருந்து விடுபடுவாய்.",
        '0.1': "இது வித்தைகளின் அரசன், ரகசியங்களின் அரசன், உன்னதமான தூய்மைப்படுத்தி; நேரடியாக உணரக்கூடியது, தர்மத்துக்கு இசைந்தது, கடைப்பிடிக்க மிக எளியது, அழிவற்றது.",
        '0.2': "பகைவரை வாட்டுபவனே, இந்த தர்மத்தில் நம்பிக்கை இல்லாதவர்கள் என்னை அடையாமல் மரணம் நிறைந்த ஸம்ஸார வழிக்குத் திரும்புகின்றனர்.",
        '0.3': "வெளிப்படாத வடிவுடைய என்னால் இவ்வுலகம் முழுவதும் வியாபிக்கப்பட்டுள்ளது. எல்லா உயிர்களும் என்னில் உள்ளன; ஆனால் நான் அவற்றில் நிலைகொண்டிருக்கவில்லை.",
        '0.4': "ஆயினும் உயிர்கள் என்னில் இல்லை — என் இறை யோகத்தைப் பார்! என் ஆத்மா உயிர்களைத் தாங்குவதும் தோற்றுவிப்பதுமாயினும் அவற்றில் உறைவதில்லை.",
        '0.5': "எங்கும் இயங்கும் பெருங்காற்று எப்போதும் ஆகாயத்திலேயே நிலைத்திருப்பது போல, எல்லா உயிர்களும் என்னில் நிலைத்துள்ளன என்று உணர்.",
        '0.6': "குந்தியின் மகனே, கல்பத்தின் முடிவில் எல்லா உயிர்களும் என் பிரக்ருதியை அடைகின்றன; கல்பத்தின் தொடக்கத்தில் நான் அவற்றை மீண்டும் படைக்கிறேன்.",
        '0.7': "என் பிரக்ருதியைக் கொண்டு, பிரக்ருதியின் ஆட்சியால் தன்வசமற்ற இந்த முழு உயிர்க்கூட்டத்தையும் நான் மீண்டும் மீண்டும் படைக்கிறேன்.",
        '0.8': "தனஞ்ஜயா, அச்செயல்கள் என்னைக் கட்டுவதில்லை; ஏனெனில் நான் அச்செயல்களில் பற்றின்றிப் பாராமுகன் போல இருக்கிறேன்.",
        '0.9': "குந்தியின் மகனே, என் மேற்பார்வையில் பிரக்ருதி அசைவன அசையாதன அனைத்தையும் தோற்றுவிக்கிறது; இக்காரணத்தால் உலகம் சுழல்கிறது.",
        '0.10': "மனித வடிவம் கொண்ட என்னை மூடர்கள் அலட்சியம் செய்கின்றனர்; எல்லா உயிர்களுக்கும் மகேஸ்வரனான என் உன்னத இயல்பை அவர்கள் அறியார்.",
        '0.11': "வீண் நம்பிக்கை, வீண் செயல், வீண் அறிவு உடைய விவேகமற்ற அவர்கள் மயக்கும் ராக்ஷஸ, அசுர இயல்பைச் சார்ந்திருக்கின்றனர்.",
        '0.12': "ஆனால் பார்த்தா, தெய்வீக இயல்பைச் சார்ந்த மகாத்மாக்கள் என்னை உயிர்களின் மூலமும் அழிவற்றவனுமாக அறிந்து வேறு நாட்டமின்றி வழிபடுகின்றனர்.",
        '0.13': "இடைவிடாமல் என்னைப் புகழ்ந்து பாடி, உறுதியான விரதத்துடன் முயன்று, பக்தியுடன் என்னை வணங்கி, எப்போதும் இணைந்தவர்களாய் என்னை உபாசிக்கின்றனர்.",
        '0.14': "வேறு சிலர் ஞான யஜ்ஞத்தால் என்னை வழிபட்டு, ஒன்றாகவும் தனியாகவும் பலவிதமாகவும் எங்கும் முகமுடைய என்னை உபாசிக்கின்றனர்.",
        '0.15': "வேள்விச் சடங்கு நான், யஜ்ஞம் நான், பித்ருக்களுக்கான ஸ்வதா நான், மூலிகை நான்; மந்திரம் நான், நெய் நானே, அக்னி நான், ஆகுதியும் நானே.",
        '0.16': "இவ்வுலகின் தந்தை நான், தாய், தாங்குபவன், பாட்டன் நான்; அறியப்பட வேண்டியவன், தூய்மைப்படுத்துபவன், ஓங்காரம், ரிக், ஸாம, யஜுர் வேதங்களும் நானே.",
        '0.17': "அடையும் இலக்கு, தாங்குபவன், தலைவன், சாட்சி, உறைவிடம், புகலிடம், நண்பன் நான்; தோற்றம், ஒடுக்கம், ஆதாரம், கருவூலம், அழியாத விதை நான்.",
        '0.18': "நானே வெப்பம் தருகிறேன்; மழையைத் தடுக்கிறேன், பொழிவிக்கிறேன். அர்ஜுனா, அமரத்துவமும் மரணமும் உள்ளதும் இல்லாததும் நானே.",
        '0.19': "மூன்று வேதங்களை அறிந்தவர்கள், ஸோமம் அருந்தியவர்கள், பாவம் நீங்கியவர்கள் யஜ்ஞங்களால் என்னை வழிபட்டுச் சுவர்க்கம் வேண்டுகின்றனர். அவர்கள் புண்ணியமான இந்திர லோகத்தை அடைந்து சுவர்க்கத்தில் தேவர்களின் தெய்வீக இன்பங்களை அனுபவிக்கின்றனர்.",
        '0.20': "அவர்கள் அந்தப் பரந்த சுவர்க்க உலகை அனுபவித்து, புண்ணியம் தீர்ந்ததும் மனித உலகில் நுழைகின்றனர். இவ்வாறு மூன்று வேதங்களின் தர்மத்தைப் பின்பற்றி இன்பங்களை விரும்புவோர் போவதும் வருவதுமாகவே இருக்கின்றனர்.",
        '0.21': "வேறு நாட்டமின்றி என்னையே எண்ணி வழிபடுபவர்களுக்கு, எப்போதும் என்னுடன் இணைந்திருக்கும் அவர்களின் யோக க்ஷேமத்தை (இல்லாததைத் தருவதையும் உள்ளதைக் காப்பதையும்) நானே ஏற்கிறேன்.",
        '0.22': "குந்தியின் மகனே, நம்பிக்கையுடன் பிற தேவதைகளை வழிபடும் பக்தர்களும் என்னையே வழிபடுகின்றனர்; ஆனால் முறைப்படி அல்ல.",
        '0.23': "எல்லா யஜ்ஞங்களையும் அனுபவிப்பவனும் தலைவனும் நானே. ஆனால் அவர்கள் என்னை உண்மையில் அறிவதில்லை; ஆகவே அவர்கள் வீழ்கின்றனர்.",
        '0.24': "தேவர்களை வழிபடுவோர் தேவர்களை அடைகின்றனர்; பித்ருக்களை வழிபடுவோர் பித்ருக்களை அடைகின்றனர்; பூதங்களை வழிபடுவோர் பூதங்களை அடைகின்றனர்; என்னை வழிபடுவோர் என்னையே அடைகின்றனர்.",
        '0.25': "யார் பக்தியுடன் எனக்கு இலை, மலர், கனி, நீர் படைக்கிறார்களோ, தூய மனமுடையவன் பக்தியுடன் அளித்த அதை நான் ஏற்கிறேன்.",
        '0.26': "குந்தியின் மகனே, நீ எதைச் செய்தாலும், எதை உண்டாலும், எதை ஆகுதியாக்கினாலும், எதைத் தானம் செய்தாலும், எந்தத் தவம் செய்தாலும் அதை எனக்கு அர்ப்பணமாகச் செய்.",
        '0.27': "இவ்வாறு நல்ல தீய பலன்களைத் தரும் வினைத் தளைகளிலிருந்து நீ விடுபடுவாய்; துறவு யோகத்தில் இணைந்த மனத்துடன் விடுதலை பெற்று என்னையே அடைவாய்.",
        '0.28': "நான் எல்லா உயிர்களிடமும் சமமானவன்; எனக்கு வெறுப்புக்குரியவனும் இல்லை, பிரியமானவனும் இல்லை. ஆனால் பக்தியுடன் என்னை வழிபடுபவர்கள் என்னில் இருக்கிறார்கள்; நானும் அவர்களில் இருக்கிறேன்.",
        '0.29': "மிகத் தீய நடத்தை உடையவனும் வேறு நாட்டமின்றி என்னை வழிபட்டால் அவனை நல்லவனாகவே கருத வேண்டும்; ஏனெனில் அவன் சரியான உறுதியை மேற்கொண்டுள்ளான்.",
        '0.30': "அவன் விரைவில் தர்மாத்மா ஆகிறான்; நிலையான அமைதியை அடைகிறான். குந்தியின் மகனே, உறுதியாக அறி: என் பக்தன் ஒருபோதும் அழிவதில்லை.",
        '0.31': "பார்த்தா, என்னைச் சரணடைபவர்கள் — தாழ்ந்த பிறப்பினரானாலும், பெண்களானாலும், வைசியர்களானாலும், சூத்திரர்களானாலும் — அவர்களும் பரம கதியை அடைகின்றனர்.",
        '0.32': "அப்படியிருக்க, புண்ணியமுடைய பிராம்மணர்களும் பக்தர்களான ராஜரிஷிகளும் அடைவதைப் பற்றிச் சொல்லவும் வேண்டுமா! நிலையற்றதும் இன்பமற்றதுமான இவ்வுலகை அடைந்த நீ என்னை வழிபடு.",
        '0.33': "என்னிடம் மனத்தைச் செலுத்து, என் பக்தனாகு, என்னை வழிபடு, என்னை வணங்கு. இவ்வாறு உன்னை என்னுடன் இணைத்து, என்னையே பரம இலக்காகக் கொண்டு நீ என்னையே அடைவாய்.",
        '0.34': "ஓம் தத் ஸத். உபநிஷத்தும் பிரம்மவித்யையும் யோகசாஸ்திரமுமான ஸ்ரீமத் பகவத்கீதையில், ஸ்ரீகிருஷ்ண-அர்ஜுன உரையாடலில் \"ராஜவித்யா ராஜகுஹ்ய யோகம்\" என்னும் ஒன்பதாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
  },
};
